input.content:
@font-face {
  font-family: 'Cinzel'; src: url('../assets/fonts/cinzel.woff2') format('woff2'); font-weight: 600 900; font-display: swap;
}
@font-face {
  font-family: 'Nunito'; src: url('../assets/fonts/nunito.woff2') format('woff2'); font-weight: 200 900; font-display: swap;
}

:root {
  --ink: #07121b;
  --ink2: #0b1d29;
  --ink3: #102a38;
  --gold: #ffd166;
  --gold2: #f0a83c;
  --teal: #6fe8d4;
  --teal2: #36b7b0;
  --rose: #ff7ba9;
  --violet: #b18aff;
  --text: #edf7f6;
  --muted: #9fb4bd;
  --line: rgba(255, 219, 145, .18);
  --line2: rgba(159, 227, 220, .14);
  --glass: rgba(8, 22, 31, .74);
  --glass2: rgba(11, 30, 41, .9);
  --rarity-common: #9fb4c7;
  --rarity-rare: #4fc3f7;
  --rarity-epic: #b46cf5;
  --rarity-legendary: #ffb545;
  --rarity-mythical: #ff6bd6;
  --shadow: 0 24px 70px rgba(0, 0, 0, .5);
  --safe-top: env(safe-area-inset-top, 0px);
  --safe-bottom: env(safe-area-inset-bottom, 0px);
}

* { box-sizing: border-box; -webkit-tap-highlight-color: transparent; }
html, body { margin: 0; padding: 0; height: 100%; overflow: hidden; background: var(--ink); }
body {
  font-family: 'Nunito', system-ui, -apple-system, sans-serif;
  color: var(--text); font-size: 15px; overscroll-behavior: none;
  user-select: none; -webkit-user-select: none; touch-action: manipulation;
}
button, input, select { font-family: inherit; color: inherit; }
button { cursor: pointer; border: 0; background: none; }
h1, h2, h3, h4 { font-family: 'Cinzel', Georgia, serif; margin: 0; font-weight: 700; letter-spacing: .04em; }
#app { position: fixed; inset: 0; overflow: hidden; }
#stage { position: absolute; inset: 0; }
.game-canvas { display: block; width: 100%; height: 100%; touch-action: none; background: #0a1621; }

/* ── boot ───────────────────────────────────────────────────────────────── */
.boot {
  position: absolute; inset: 0; z-index: 90; display: grid; place-items: center;
  background: radial-gradient(ellipse at 50% 38%, #12384a 0%, #0a1c27 42%, #050c12 100%);
  transition: opacity .7s ease, visibility .7s;
}
.boot.done { opacity: 0; visibility: hidden; }
.boot-inner { text-align: center; position: relative; z-index: 2; padding: 30px; }
.boot-vignette { position: absolute; inset: 0; background: radial-gradient(ellipse at 50% 50%, transparent 40%, rgba(0,0,0,.6) 100%); }
.crest { width: 66px; height: 66px; margin: 0 auto 8px; filter: drop-shadow(0 0 18px rgba(255, 200, 100, .4)); }
.crest svg { width: 100%; height: 100%; }
.crest-wing { fill: url(#none); fill: #ffd166; opacity: .85; }
.crest-wing.right { fill: #ffd166; }
.crest-body { fill: #f7e7c1; }
.crest-eye { fill: #123744; }
.big-crest { width: 96px; height: 96px; animation: crestFloat 4s ease-in-out infinite; }
.logo-big {
  font-size: clamp(38px, 8vw, 74px); line-height: .96; color: #f7eccd;
  text-shadow: 0 2px 0 #3b2a15, 0 10px 40px rgba(255, 190, 80, .35);
  background: linear-gradient(180deg, #fff8e3 10%, #ffd166 60%, #d4953c 100%);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
}
.logo-big span { display: inline-block; color: transparent; background: linear-gradient(180deg, #ffd166, #ff9f66); -webkit-background-clip: text; background-clip: text; }
.logo-sub { font-family: 'Cinzel'; letter-spacing: .55em; font-size: clamp(9px, 1.6vw, 13px); color: var(--teal); opacity: .85; margin: 14px 0 34px 0; text-indent: .55em; }
.boot-bar { width: min(320px, 66vw); height: 3px; background: rgba(255,255,255,.1); margin: 0 auto; border-radius: 99px; overflow: hidden; }
.boot-bar i { display: block; height: 100%; width: 8%; background: linear-gradient(90deg, var(--teal2), var(--gold)); box-shadow: 0 0 16px var(--gold); transition: width .35s; }
.boot-text { font-size: 12px; letter-spacing: .16em; color: var(--muted); margin-top: 14px; text-transform: uppercase; }
@keyframes crestFloat { 0%,100% { transform: translateY(0) } 50% { transform: translateY(-7px) } }

/* ── UI frame ───────────────────────────────────────────────────────────── */
.ui { position: absolute; inset: 0; z-index: 5; pointer-events: none; }
.hidden { display: none !important; }

.topbar {
  position: absolute; top: 0; left: 0; right: 0; z-index: 20;
  display: flex; align-items: center; justify-content: space-between; gap: 12px;
  padding: calc(12px + var(--safe-top)) clamp(14px, 3vw, 30px) 12px;
  pointer-events: none;
  background: linear-gradient(180deg, rgba(3, 10, 15, .82) 0%, rgba(3, 10, 15, .35) 62%, transparent 100%);
}
.rider-card { display: flex; align-items: center; gap: 10px; pointer-events: auto; }
.rider-avatar {
  width: 42px; height: 42px; border-radius: 50%; display: grid; place-items: center;
  font-family: 'Cinzel'; font-weight: 900; font-size: 18px; color: #241b0d;
  background: linear-gradient(145deg, #ffe8a8, #e3a43a); border: 1px solid #ffeec6;
  box-shadow: 0 0 0 3px rgba(255, 209, 102, .14), 0 4px 12px rgba(0,0,0,.35);
}
.rider-meta { display: flex; flex-direction: column; gap: 2px; min-width: 0; }
.rider-name { font-family: 'Cinzel'; font-size: 13px; color: #fff3d4; letter-spacing: .04em; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; max-width: 32vw; }
.rider-level { font-size: 9px; letter-spacing: .16em; color: var(--muted); }
.rider-level b { color: var(--gold); }
.xp-mini { width: 92px; height: 3px; border-radius: 9px; background: rgba(255,255,255,.1); overflow: hidden; }
.xp-mini i { display: block; height: 100%; background: linear-gradient(90deg, var(--teal), var(--gold)); box-shadow: 0 0 8px rgba(111,232,212,.7); transition: width .4s; }
.top-actions { display: flex; align-items: center; gap: 8px; pointer-events: auto; }
.currency {
  display: flex; align-items: center; gap: 7px; padding: 7px 12px; border-radius: 99px;
  background: rgba(9, 23, 32, .68); border: 1px solid var(--line);
  font-size: 13px; color: #fff1cf; backdrop-filter: blur(8px); -webkit-backdrop-filter: blur(8px);
}
.currency b { font-variant-numeric: tabular-nums; font-weight: 800; font-size: 13px; }
.coin-ico { color: var(--gold); font-size: 15px; text-shadow: 0 0 10px rgba(255,209,102,.5); }
.gem-ico { color: var(--teal); font-size: 13px; text-shadow: 0 0 10px rgba(111,232,212,.6); }
.icon-btn {
  width: 38px; height: 38px; border-radius: 12px; display: grid; place-items: center; font-size: 17px;
  background: rgba(9,23,32,.68); border: 1px solid var(--line); color: #ffe9b3;
  backdrop-filter: blur(8px); transition: .2s;
}
.icon-btn:hover { background: rgba(255,209,102,.12); transform: translateY(-1px); }

/* ── screens ────────────────────────────────────────────────────────────── */
.screen {
  position: absolute; inset: 0; z-index: 6; pointer-events: none;
  padding: calc(76px + var(--safe-top)) clamp(16px, 3.4vw, 44px) calc(86px + var(--safe-bottom));
  overflow-y: auto; overflow-x: hidden; -webkit-overflow-scrolling: touch;
  scrollbar-width: thin; scrollbar-color: rgba(255,209,102,.25) transparent;
}
.screen::-webkit-scrollbar { width: 5px; }
.screen::-webkit-scrollbar-thumb { background: rgba(255,209,102,.25); border-radius: 4px; }
.screen button, .screen .card, .screen .chip, .screen .pill, .screen .tab, .screen .track-card, .screen .zone-card,
.screen .dragon-row, .screen .shop-card, .screen .swatch, .screen .option, .screen .ui-hit, .screen input, .screen select,
.screen a, .screen .modal-open, .screen .skill-node, .screen .build-card, .screen .dragon-mini, .screen .leader-row {
  pointer-events: auto;
}
.screen-head { display: flex; align-items: end; justify-content: space-between; gap: 16px; margin-bottom: 20px; flex-wrap: wrap; }
.eyebrow { font-size: 10px; letter-spacing: .28em; text-transform: uppercase; color: var(--teal); margin-bottom: 5px; display: flex; align-items: center; gap: 8px; }
.eyebrow::before { content: ''; width: 18px; height: 1px; background: var(--teal); opacity: .6; }
.screen-title { font-size: clamp(24px, 3.2vw, 38px); color: #fff7e6; text-shadow: 0 6px 30px rgba(0,0,0,.5); }
.screen-sub { color: var(--muted); font-size: 13px; max-width: 620px; line-height: 1.5; margin: 6px 0 0; }
.back-btn { display: inline-flex; align-items: center; gap: 7px; padding: 9px 14px; border-radius: 99px; background: rgba(9,23,32,.7); border: 1px solid var(--line2); color: #d8ecea; font-size: 12px; font-weight: 700; letter-spacing: .06em; }

/* ── buttons ────────────────────────────────────────────────────────────── */
.btn {
  display: inline-flex; align-items: center; justify-content: center; gap: 9px;
  padding: 12px 20px; border-radius: 14px; font-weight: 800; font-size: 13px;
  letter-spacing: .05em; transition: transform .16s, box-shadow .2s, background .2s, opacity .2s;
  border: 1px solid transparent; white-space: nowrap; position: relative; overflow: hidden;
}
.btn:active { transform: scale(.97); }
.btn-primary {
  color: #2a1c08; background: linear-gradient(160deg, #ffe39a 0%, #ffd166 38%, #eda438 100%);
  border-color: #fff0c0; box-shadow: 0 8px 26px rgba(240,168,60,.32), inset 0 1px 0 #fff8dd;
  text-shadow: 0 1px 0 rgba(255,255,255,.35);
}
.btn-primary::after {
  content: ''; position: absolute; top: 0; left: -70%; width: 45%; height: 100%;
  background: linear-gradient(100deg, transparent, rgba(255,255,255,.55), transparent);
  transform: skewX(-18deg); animation: shine 4.2s ease-in-out infinite;
}
@keyframes shine { 0%, 62% { left: -70%; } 82%, 100% { left: 130%; } }
.btn-ghost { background: rgba(11, 30, 41, .72); border-color: var(--line); color: #e6f3f1; }
.btn-ghost:hover { border-color: rgba(255,209,102,.4); background: rgba(20, 44, 56, .8); }
.btn-teal { background: linear-gradient(160deg, #b4fff3, #49cabc); color: #06211f; border-color: #d6fff9; box-shadow: 0 8px 24px rgba(73,202,188,.26); }
.btn-danger { background: rgba(116, 32, 45, .7); border-color: rgba(255,123,140,.4); color: #ffd5dc; }
.btn-sm { padding: 8px 13px; font-size: 11px; border-radius: 10px; }
.btn-lg { padding: 16px 28px; font-size: 15px; border-radius: 17px; }
.btn-block { width: 100%; }
.btn:disabled, .btn.disabled { opacity: .42; filter: grayscale(.5); pointer-events: none; }
.btn .sub { font-weight: 600; font-size: 10px; opacity: .75; letter-spacing: .12em; }
.btn-ico { font-size: 17px; line-height: 1; }

/* ── menu ───────────────────────────────────────────────────────────────── */
.menu-screen {
  display: grid; grid-template-columns: minmax(300px, 500px) 1fr minmax(290px, 360px);
  align-items: center; gap: clamp(18px, 3vw, 40px);
  overflow: hidden; padding-bottom: calc(96px + var(--safe-bottom));
}
.menu-hero { align-self: center; max-width: 500px; }
.brand-line { display: flex; align-items: center; gap: 12px; margin-bottom: 10px; }
.brand-crest { width: 44px; height: 44px; flex: none; filter: drop-shadow(0 0 14px rgba(255,209,102,.4)); }
.logo-main {
  font-size: clamp(38px, 5.3vw, 66px); line-height: .92; color: #fff7e0;
  background: linear-gradient(180deg, #fff9e7 8%, #ffd166 58%, #d18c30 100%);
  -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent;
  filter: drop-shadow(0 6px 24px rgba(0,0,0,.45));
}
.logo-main em { font-style: normal; display: block; color: transparent; background: linear-gradient(180deg, #ffdc8b, #ff9966); -webkit-background-clip: text; background-clip: text; font-size: .72em; letter-spacing: .08em; }
.logo-tag { font-family: 'Cinzel'; letter-spacing: .46em; font-size: 10px; color: var(--teal); text-transform: uppercase; margin: 10px 0 0 3px; }
.menu-blurb { color: #c9dedd; line-height: 1.6; font-size: 14px; max-width: 400px; margin: 19px 0 24px; text-shadow: 0 2px 12px rgba(0,0,0,.6); }
.menu-blurb b { color: var(--gold); }
.hero-actions { display: flex; gap: 10px; flex-wrap: wrap; }
.active-dragon-strip {
  display: flex; align-items: center; gap: 11px; margin-top: 24px; padding: 9px 14px 9px 9px;
  border: 1px solid var(--line2); border-radius: 16px; background: rgba(6,19,26,.62);
  width: fit-content; backdrop-filter: blur(10px);
}
.active-dragon-strip img { width: 44px; height: 44px; border-radius: 12px; border: 1px solid rgba(255,255,255,.12); }
.strip-meta { display: flex; flex-direction: column; }
.strip-meta b { font-family: 'Cinzel'; font-size: 13px; color: #fff2d5; }
.strip-meta span { font-size: 10px; color: var(--muted); letter-spacing: .08em; }
.menu-cards { display: flex; flex-direction: column; gap: 14px; align-self: center; width: 100%; max-width: 370px; justify-self: end; }
.card {
  border: 1px solid var(--line); border-radius: 18px; padding: 16px;
  background: linear-gradient(160deg, rgba(13, 34, 45, .88), rgba(6, 18, 26, .82));
  backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);
  box-shadow: var(--shadow); position: relative; overflow: hidden;
}
.card::before { content: ''; position: absolute; inset: 0; pointer-events: none; background: linear-gradient(120deg, rgba(255,255,255,.06), transparent 30%); }
.card-head { display: flex; align-items: center; justify-content: space-between; gap: 10px; margin-bottom: 10px; }
.card-title { font-family: 'Cinzel'; font-size: 14px; color: #fff1d2; }
.card-kicker { font-size: 9px; letter-spacing: .2em; color: var(--teal); text-transform: uppercase; }
.event-card { border-color: rgba(255, 146, 96, .32); background: linear-gradient(150deg, rgba(87, 34, 37, .8), rgba(20, 23, 38, .88)); }
.event-card .card-title { color: #ffe0ba; }
.event-banner { display: flex; align-items: center; gap: 12px; margin: 4px 0 12px; }
.event-orb { width: 50px; height: 50px; border-radius: 50%; display: grid; place-items: center; font-size: 24px; background: radial-gradient(circle at 35% 30%, #ffeab0, #ff9a5c 55%, #b73c53); box-shadow: 0 0 28px rgba(255,140,80,.45); animation: crestFloat 4.5s ease-in-out infinite; }
.event-name { font-family: 'Cinzel'; font-size: 17px; color: #fff4dc; line-height: 1.15; }
.event-sub { font-size: 10.5px; color: #ffc9b4; margin-top: 3px; }
.bar { height: 6px; border-radius: 99px; background: rgba(255,255,255,.09); overflow: hidden; }
.bar i { display: block; height: 100%; border-radius: 99px; background: linear-gradient(90deg, var(--teal2), var(--gold)); box-shadow: 0 0 10px rgba(255,209,102,.4); transition: width .5s; }
.bar-label { display: flex; justify-content: space-between; font-size: 10px; color: var(--muted); margin: 6px 0 0; }
.daily-list { list-style: none; padding: 0; margin: 0; display: flex; flex-direction: column; gap: 8px; }
.daily-item { display: grid; grid-template-columns: 26px 1fr auto; align-items: center; gap: 8px; font-size: 11.5px; }
.daily-icon { width: 25px; height: 25px; border-radius: 8px; display: grid; place-items: center; background: rgba(255,255,255,.06); color: var(--gold); font-size: 13px; }
.daily-text { color: #cfdfde; display: flex; flex-direction: column; gap: 1px; }
.daily-text small { color: var(--muted); font-size: 9.5px; }
.daily-claim { font-size: 10px; font-weight: 800; padding: 5px 8px; border-radius: 7px; border: 1px solid var(--line); color: var(--gold); background: rgba(255,209,102,.08); }
.daily-claim.ready { background: var(--gold); color: #2a1c08; border-color: #ffe9b1; animation: pulseGold 1.6s infinite; }
.daily-claim.done { color: var(--muted); border-color: transparent; opacity: .6; }
@keyframes pulseGold { 0%,100% { box-shadow: 0 0 0 0 rgba(255,209,102,.25) } 50% { box-shadow: 0 0 0 5px rgba(255,209,102,0) } }

/* ── bottom nav ─────────────────────────────────────────────────────────── */
.bottomnav {
  position: absolute; left: 50%; bottom: calc(14px + var(--safe-bottom)); transform: translateX(-50%);
  z-index: 22; display: flex; align-items: center; gap: 3px; padding: 6px;
  background: rgba(6, 18, 26, .86); border: 1px solid var(--line);
  border-radius: 20px; box-shadow: 0 12px 40px rgba(0,0,0,.55), inset 0 1px 0 rgba(255,255,255,.06);
  backdrop-filter: blur(16px); pointer-events: auto;
}
.bottomnav.hidden { display: none; }
.nav-btn {
  display: flex; flex-direction: column; align-items: center; gap: 2px; min-width: 68px;
  padding: 8px 11px; border-radius: 14px; color: #8fa9b1; transition: .2s; position: relative;
  pointer-events: auto;
}
.nav-btn .ico { font-size: 18px; line-height: 1; filter: grayscale(.4); transition: .2s; }
.nav-btn .lbl { font-size: 8.5px; letter-spacing: .13em; text-transform: uppercase; font-weight: 800; }
.nav-btn:hover { color: #d9edeb; background: rgba(255,255,255,.04); }
.nav-btn.active { color: var(--gold); background: rgba(255,209,102,.09); }
.nav-btn.active::before { content: ''; position: absolute; top: -1px; left: 50%; transform: translateX(-50%); width: 16px; height: 2px; border-radius: 9px; background: var(--gold); box-shadow: 0 0 10px var(--gold); }
.nav-btn.active .ico { filter: none; text-shadow: 0 0 12px rgba(255,209,102,.6); }

/* ── race hub ───────────────────────────────────────────────────────────── */
.hub-grid { display: grid; grid-template-columns: 1fr 360px; gap: 20px; align-items: start; max-width: 1240px; margin: 0 auto; }
.hub-main { min-width: 0; }
.mode-pills { display: flex; gap: 8px; overflow-x: auto; padding-bottom: 6px; margin-bottom: 18px; scrollbar-width: none; }
.mode-pills::-webkit-scrollbar { display: none; }
.mode-pill {
  padding: 9px 14px; border-radius: 99px; border: 1px solid var(--line2); background: rgba(9,23,32,.6);
  color: #b4c8cb; font-size: 11.5px; font-weight: 800; letter-spacing: .03em; white-space: nowrap; transition: .2s;
  display: flex; align-items: center; gap: 7px; pointer-events: auto;
}
.mode-pill .ico { font-size: 13px; }
.mode-pill.active { color: #2b1d08; background: linear-gradient(150deg, #ffe39a, #edaa40); border-color: #fff0c4; box-shadow: 0 4px 16px rgba(240,168,60,.28); }
.track-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 12px; }
.track-card {
  position: relative; min-height: 138px; border-radius: 17px; overflow: hidden; border: 1px solid var(--line2);
  padding: 14px; display: flex; flex-direction: column; justify-content: space-between; cursor: pointer;
  background: linear-gradient(165deg, var(--tc1, #295e6b), var(--tc2, #102b37));
  transition: transform .2s, border-color .2s, box-shadow .2s;
}
.track-card:hover { transform: translateY(-3px); border-color: rgba(255,209,102,.45); box-shadow: 0 12px 30px rgba(0,0,0,.35); }
.track-card.selected { border-color: var(--gold); box-shadow: 0 0 0 1px var(--gold), 0 12px 34px rgba(0,0,0,.4); }
.track-card::before { content: ''; position: absolute; inset: 0; background: radial-gradient(120% 80% at 80% 0%, rgba(255,255,255,.14), transparent 60%), linear-gradient(0deg, rgba(3,10,15,.72), transparent 80%); }
.track-card.locked { filter: saturate(.35); }
.track-top, .track-bottom { position: relative; z-index: 1; display: flex; align-items: flex-start; justify-content: space-between; gap: 8px; }
.track-icon { font-size: 22px; color: #fff2cf; text-shadow: 0 2px 10px rgba(0,0,0,.4); }
.track-badge { font-size: 8.5px; letter-spacing: .14em; font-weight: 900; text-transform: uppercase; padding: 4px 7px; border-radius: 6px; background: rgba(4,13,19,.58); border: 1px solid rgba(255,255,255,.15); color: #ffe4a5; }
.track-name { font-family: 'Cinzel'; font-size: 16px; color: #fff8e8; line-height: 1.1; text-shadow: 0 2px 10px rgba(0,0,0,.45); }
.track-region { font-size: 9.5px; color: rgba(255,255,255,.65); letter-spacing: .08em; margin-top: 3px; }
.track-bottom { align-items: flex-end; }
.diffs { display: flex; gap: 3px; }
.diffs i { width: 5px; height: 5px; border-radius: 50%; background: rgba(255,255,255,.25); }
.diffs i.on { background: var(--gold); box-shadow: 0 0 6px rgba(255,209,102,.6); }
.track-best { font-size: 9.5px; color: #ffe9b7; font-variant-numeric: tabular-nums; }
.track-lock { position: absolute; inset: 0; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 5px; background: rgba(4,11,16,.55); color: #d7e3e3; font-size: 10px; letter-spacing: .1em; z-index: 2; backdrop-filter: blur(1px); }
.track-lock .big { font-size: 22px; }
.league-list { margin-top: 22px; }
.section-label { display: flex; align-items: center; justify-content: space-between; margin: 0 0 10px; }
.section-label h3 { font-family: 'Cinzel'; font-size: 14px; color: #ffe9c0; letter-spacing: .1em; }
.section-label span { font-size: 10px; color: var(--muted); }
.league-card {
  display: flex; align-items: center; gap: 12px; padding: 12px 14px; border: 1px solid var(--line2);
  border-radius: 14px; background: rgba(9,23,32,.58); margin-bottom: 8px; transition: .2s; cursor: pointer;
}
.league-card:hover { background: rgba(18,42,52,.7); border-color: rgba(255,209,102,.35); }
.league-card.locked { opacity: .52; filter: saturate(.5); }
.league-emblem { width: 40px; height: 40px; flex: none; border-radius: 12px; display: grid; place-items: center; font-size: 19px; background: linear-gradient(150deg, rgba(255,209,102,.18), rgba(111,232,212,.1)); border: 1px solid var(--line); }
.league-info { flex: 1; min-width: 0; }
.league-info b { display: block; font-family: 'Cinzel'; font-size: 13px; color: #f4ecd7; }
.league-info span { display: block; font-size: 10px; color: var(--muted); margin-top: 2px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }
.league-go { font-size: 11px; font-weight: 800; color: var(--gold); white-space: nowrap; }
.league-progress { font-size: 9px; color: var(--teal); }
.race-side { display: flex; flex-direction: column; gap: 14px; position: sticky; top: 0; }
.side-panel { border: 1px solid var(--line); border-radius: 18px; padding: 16px; background: linear-gradient(165deg, rgba(13,34,45,.9), rgba(6,18,26,.86)); backdrop-filter: blur(14px); box-shadow: var(--shadow); }
.side-panel h3 { font-size: 13px; color: #fff0d2; letter-spacing: .08em; margin-bottom: 10px; }
.track-detail-name { font-family: 'Cinzel'; font-size: 23px; color: #fff6e1; line-height: 1.1; margin: 4px 0 2px; }
.track-detail-region { font-size: 10px; letter-spacing: .14em; color: var(--teal); text-transform: uppercase; }
.track-detail-desc { font-size: 12px; line-height: 1.55; color: #b8cdcf; margin: 10px 0 14px; }
.mode-desc { font-size: 11px; color: #c7dcda; line-height: 1.5; padding: 10px; border-radius: 10px; background: rgba(255,255,255,.04); border: 1px solid var(--line2); margin-bottom: 13px; }
.mode-desc b { color: var(--gold); }
.side-dragon { display: flex; align-items: center; gap: 10px; padding: 8px; border-radius: 12px; background: rgba(255,255,255,.035); border: 1px solid var(--line2); margin-bottom: 12px; }
.side-dragon img { width: 50px; height: 50px; border-radius: 10px; }
.side-dragon .nm { font-family: 'Cinzel'; font-size: 12.5px; color: #ffefd3; }
.side-dragon .st { font-size: 9.5px; color: var(--muted); }
.side-dragon .lvl { margin-left: auto; font-size: 10px; font-weight: 800; color: var(--gold); }
.entry-row { display: flex; align-items: center; justify-content: space-between; font-size: 11px; color: var(--muted); margin-bottom: 10px; }
.entry-row b { color: #ffe7b2; font-weight: 800; }
.leaderboard-mini { display: flex; flex-direction: column; gap: 5px; }
.leader-row { display: grid; grid-template-columns: 20px 1fr auto; align-items: center; gap: 8px; font-size: 11px; padding: 4px 0; border-bottom: 1px solid rgba(255,255,255,.04); }
.leader-row .pos { color: var(--gold); font-weight: 900; font-size: 10px; }
.leader-row .nm { color: #d4e4e4; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.leader-row .tm { font-variant-numeric: tabular-nums; color: #9fb4bd; font-size: 10px; }
.leader-row.me .nm { color: var(--gold); font-weight: 800; }
.champ-strip { display: flex; align-items: center; gap: 9px; padding: 10px; border-radius: 12px; background: linear-gradient(100deg, rgba(255,209,102,.1), rgba(111,232,212,.05)); border: 1px solid var(--line); margin-bottom: 10px; font-size: 10px; color: #d9e8e5; }
.champ-strip .ico { font-size: 17px; }
.champ-strip b { color: var(--gold); }

/* ── hangar ─────────────────────────────────────────────────────────────── */
.hangar-screen { padding-bottom: calc(90px + var(--safe-bottom)); }
.hangar-layout { display: grid; grid-template-columns: 250px 1fr 380px; gap: 18px; height: calc(100dvh - 170px); min-height: 440px; max-width: 1440px; margin: 0 auto; }
.hangar-side { display: flex; flex-direction: column; gap: 10px; min-height: 0; }
.side-title { display: flex; align-items: center; justify-content: space-between; margin-bottom: 2px; }
.side-title h2 { font-size: 15px; color: #fff1d4; }
.side-title span { font-size: 10px; color: var(--muted); }
.dragon-list { overflow-y: auto; display: flex; flex-direction: column; gap: 7px; padding-right: 4px; scrollbar-width: thin; }
.dragon-row {
  display: flex; align-items: center; gap: 9px; padding: 7px; border-radius: 12px; border: 1px solid transparent;
  background: rgba(9,23,32,.6); cursor: pointer; transition: .18s; text-align: left;
}
.dragon-row:hover { background: rgba(20,44,55,.7); border-color: var(--line2); }
.dragon-row.active { border-color: var(--gold); background: linear-gradient(100deg, rgba(255,209,102,.12), rgba(9,23,32,.7)); box-shadow: inset 3px 0 0 var(--gold); }
.dragon-row img { width: 44px; height: 44px; border-radius: 9px; border: 1px solid rgba(255,255,255,.1); }
.dragon-row .nm { font-family: 'Cinzel'; font-size: 12px; color: #f7eedb; line-height: 1.1; }
.dragon-row .sub { font-size: 9px; color: var(--muted); margin-top: 2px; display: flex; align-items: center; gap: 5px; }
.rarity-dot { width: 5px; height: 5px; border-radius: 50%; display: inline-block; }
.dragon-row .lvl { margin-left: auto; font-size: 9.5px; font-weight: 800; color: var(--gold); background: rgba(255,209,102,.08); padding: 3px 5px; border-radius: 5px; }
.locked-row { opacity: .55; }
.locked-row .lock { margin-left: auto; font-size: 12px; }
.hangar-center { position: relative; pointer-events: none; display: flex; align-items: flex-end; justify-content: center; padding-bottom: 14px; }
.hangar-center .stage-hint { pointer-events: none; font-size: 10px; color: rgba(255,255,255,.5); letter-spacing: .12em; text-transform: uppercase; background: rgba(4,13,19,.4); padding: 6px 12px; border-radius: 99px; }
.hangar-panel {
  display: flex; flex-direction: column; min-height: 0; border: 1px solid var(--line); border-radius: 20px;
  background: linear-gradient(170deg, rgba(11,29,39,.93), rgba(5,16,23,.9)); backdrop-filter: blur(16px);
  box-shadow: var(--shadow); overflow: hidden;
}
.dragon-head { padding: 15px 16px 12px; border-bottom: 1px solid var(--line2); position: relative; }
.dragon-head::before { content: ''; position: absolute; inset: 0; background: linear-gradient(120deg, var(--rarity-glow, transparent), transparent 55%); opacity: .18; pointer-events: none; }
.dragon-rarity { display: inline-flex; align-items: center; gap: 5px; font-size: 8.5px; letter-spacing: .18em; text-transform: uppercase; font-weight: 900; color: var(--rarity, var(--gold)); margin-bottom: 4px; }
.dragon-rarity::before { content: '◆'; font-size: 8px; }
.dragon-title { font-family: 'Cinzel'; font-size: 24px; color: #fff7e3; line-height: 1.05; }
.dragon-epithet { font-size: 10.5px; color: var(--teal); letter-spacing: .06em; margin-top: 3px; }
.level-row { display: flex; align-items: center; gap: 9px; margin-top: 10px; }
.level-badge { font-size: 10px; font-weight: 900; color: #2a1c08; background: linear-gradient(140deg, #ffe39a, #eda438); padding: 4px 8px; border-radius: 6px; }
.level-xp { flex: 1; }
.level-xp .bar { height: 5px; }
.level-xp .txt { font-size: 9px; color: var(--muted); margin-top: 3px; display: flex; justify-content: space-between; }
.bond-box { padding: 10px 16px; border-bottom: 1px solid var(--line2); }
.bond-head { display: flex; justify-content: space-between; font-size: 10px; color: var(--muted); margin-bottom: 5px; }
.bond-head b { color: var(--rose); }
.bond-actions { display: flex; gap: 5px; margin-top: 8px; }
.bond-actions button { flex: 1; padding: 7px 4px; border-radius: 8px; background: rgba(255,255,255,.05); border: 1px solid var(--line2); font-size: 9.5px; font-weight: 800; color: #dbe9e8; display: flex; flex-direction: column; align-items: center; gap: 2px; transition: .18s; }
.bond-actions button:hover { background: rgba(255,209,102,.1); border-color: rgba(255,209,102,.35); }
.bond-actions button span { font-size: 14px; }
.tabs { display: flex; border-bottom: 1px solid var(--line2); padding: 0 8px; flex: none; }
.tab { padding: 10px 9px; font-size: 10px; font-weight: 900; letter-spacing: .08em; text-transform: uppercase; color: #7d969d; border-bottom: 2px solid transparent; margin-bottom: -1px; transition: .18s; }
.tab.active { color: var(--gold); border-color: var(--gold); }
.tab-body { padding: 13px 16px 18px; overflow-y: auto; flex: 1; scrollbar-width: thin; }
.tab-body::-webkit-scrollbar { width: 4px; }
.tab-body::-webkit-scrollbar-thumb { background: rgba(255,209,102,.2); border-radius: 4px; }
.stat-list { display: flex; flex-direction: column; gap: 9px; }
.stat-line { display: grid; grid-template-columns: 68px 1fr 30px 35px; align-items: center; gap: 7px; font-size: 10.5px; color: #b9cfcf; }
.stat-line .val { text-align: right; font-weight: 800; color: #f1e5c7; font-size: 11px; }
.stat-bar { height: 5px; border-radius: 5px; background: rgba(255,255,255,.08); overflow: hidden; }
.stat-bar i { display: block; height: 100%; border-radius: 5px; background: linear-gradient(90deg, var(--teal2), var(--teal)); }
.stat-line:nth-child(2) .stat-bar i { background: linear-gradient(90deg, #d68a3a, var(--gold)); }
.stat-line:nth-child(3) .stat-bar i { background: linear-gradient(90deg, #8a5bd6, var(--violet)); }
.stat-line:nth-child(4) .stat-bar i { background: linear-gradient(90deg, #c94b7a, var(--rose)); }
.up-btn { font-size: 9px; font-weight: 900; padding: 4px 5px; border-radius: 6px; background: rgba(255,209,102,.1); border: 1px solid rgba(255,209,102,.25); color: var(--gold); }
.up-btn:disabled { opacity: .3; }
.ability-card { margin-top: 12px; padding: 10px; border-radius: 11px; border: 1px solid rgba(111,232,212,.25); background: linear-gradient(120deg, rgba(111,232,212,.08), transparent); }
.ability-card .ab-name { font-family: 'Cinzel'; font-size: 12px; color: var(--teal); }
.ability-card .ab-desc { font-size: 10.5px; color: #b9cecd; margin-top: 3px; line-height: 1.45; }
.ability-card .ab-cd { float: right; font-size: 9px; color: var(--muted); }
.cos-title { font-size: 9px; letter-spacing: .16em; text-transform: uppercase; color: var(--muted); margin: 11px 0 7px; }
.cos-grid { display: grid; grid-template-columns: repeat(3, 1fr); gap: 6px; }
.swatch { border: 1px solid var(--line2); border-radius: 9px; padding: 7px 5px; text-align: center; cursor: pointer; background: rgba(255,255,255,.03); transition: .18s; }
.swatch:hover { border-color: rgba(255,209,102,.4); }
.swatch.equipped { border-color: var(--gold); background: rgba(255,209,102,.1); }
.swatch .sw-color { width: 20px; height: 20px; border-radius: 50%; margin: 0 auto 4px; border: 2px solid rgba(255,255,255,.35); box-shadow: 0 0 10px rgba(0,0,0,.3); }
.swatch .sw-name { font-size: 8.5px; color: #cadcdb; line-height: 1.15; }
.swatch .sw-lock { font-size: 8px; color: var(--gold); margin-top: 2px; }
.skill-paths { display: flex; flex-direction: column; gap: 13px; }
.skill-path-label { font-size: 9px; letter-spacing: .16em; text-transform: uppercase; color: var(--muted); display: flex; justify-content: space-between; margin-bottom: 5px; }
.skill-nodes { display: flex; gap: 5px; }
.skill-node { flex: 1; padding: 7px 5px; border-radius: 8px; border: 1px solid var(--line2); background: rgba(255,255,255,.025); font-size: 8.5px; line-height: 1.25; color: #b6cacb; text-align: left; position: relative; min-height: 54px; }
.skill-node b { display: block; font-size: 9px; color: #e7e1ce; margin-bottom: 2px; }
.skill-node.locked { opacity: .55; }
.skill-node.owned { border-color: rgba(111,232,212,.5); background: rgba(111,232,212,.1); }
.skill-node.available { border-color: rgba(255,209,102,.45); box-shadow: 0 0 12px rgba(255,209,102,.08); }
.skill-node .cost { position: absolute; top: 4px; right: 5px; font-size: 7.5px; color: var(--gold); }
.skill-points { display: inline-flex; align-items: center; gap: 5px; font-size: 10px; color: var(--gold); background: rgba(255,209,102,.08); border: 1px solid var(--line); padding: 4px 8px; border-radius: 7px; }
.lore { font-size: 12px; line-height: 1.65; color: #c3d7d5; }
.lore blockquote { border-left: 2px solid var(--gold); margin: 12px 0; padding-left: 10px; color: #a9bcbc; font-style: italic; font-size: 11px; }
.trait-list { display: flex; flex-wrap: wrap; gap: 5px; margin-top: 10px; }
.trait-chip { font-size: 9px; padding: 4px 7px; border-radius: 99px; background: rgba(255,255,255,.05); border: 1px solid var(--line2); color: #cfe0dd; }

/* ── shop ───────────────────────────────────────────────────────────────── */
.shop-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(180px, 1fr)); gap: 12px; max-width: 1240px; margin: 0 auto; }
.shop-card { border-radius: 16px; overflow: hidden; border: 1px solid var(--line2); background: linear-gradient(170deg, rgba(13,34,45,.92), rgba(6,18,26,.9)); transition: .2s; position: relative; }
.shop-card:hover { transform: translateY(-3px); border-color: rgba(255,209,102,.4); }
.shop-thumb { position: relative; aspect-ratio: 1.5; background: radial-gradient(circle at 50% 60%, var(--rarity-glow, #335), #0a1720); overflow: hidden; }
.shop-thumb img { width: 100%; height: 100%; object-fit: cover; }
.shop-info { padding: 10px 11px 12px; }
.shop-name { font-family: 'Cinzel'; font-size: 13px; color: #fff2d7; }
.shop-rar { font-size: 8px; letter-spacing: .14em; text-transform: uppercase; font-weight: 900; margin-bottom: 3px; }
.shop-desc { font-size: 9.5px; color: var(--muted); line-height: 1.4; margin: 5px 0 9px; min-height: 26px; }
.price-btn { width: 100%; padding: 7px; border-radius: 8px; background: rgba(255,209,102,.1); border: 1px solid rgba(255,209,102,.25); color: var(--gold); font-size: 10.5px; font-weight: 900; display: flex; align-items: center; justify-content: center; gap: 5px; }
.price-btn.owned { background: rgba(111,232,212,.08); color: var(--teal); border-color: rgba(111,232,212,.25); }
.price-btn:disabled { opacity: .45; }
.shop-tabs { display: flex; gap: 7px; margin-bottom: 16px; flex-wrap: wrap; max-width: 1240px; margin-left: auto; margin-right: auto; }
.shop-tab { padding: 8px 14px; border-radius: 99px; border: 1px solid var(--line2); font-size: 11px; font-weight: 800; color: #a7bfc2; background: rgba(9,23,32,.6); }
.shop-tab.active { color: #2b1d08; background: linear-gradient(150deg, #ffe39a, #eda438); border-color: #fff0c4; }
.cosmetic-card .shop-thumb { aspect-ratio: 1.7; display: grid; place-items: center; }
.cosmetic-preview { width: 54px; height: 54px; border-radius: 50%; border: 3px solid rgba(255,255,255,.45); box-shadow: 0 8px 30px rgba(0,0,0,.4); }
.featured-strip { display: grid; grid-template-columns: 1.2fr 1fr; gap: 14px; max-width: 1240px; margin: 0 auto 18px; }
.featured { border-radius: 18px; padding: 20px; border: 1px solid var(--line); position: relative; overflow: hidden; min-height: 150px; display: flex; flex-direction: column; justify-content: flex-end; background: linear-gradient(140deg, rgba(44,74,110,.85), rgba(10,24,34,.9)); }
.featured::before { content: ''; position: absolute; inset: 0; background: radial-gradient(80% 100% at 80% 10%, rgba(255,209,102,.22), transparent 60%); }
.featured .f-kicker { font-size: 9px; letter-spacing: .2em; text-transform: uppercase; color: var(--teal); position: relative; }
.featured .f-title { font-family: 'Cinzel'; font-size: 22px; color: #fff6e4; position: relative; margin-top: 4px; }
.featured .f-desc { font-size: 11px; color: #c4d8d8; position: relative; margin-top: 4px; max-width: 380px; }
.featured .f-actions { position: relative; margin-top: 12px; display: flex; gap: 7px; align-items: center; }

/* ── explore ────────────────────────────────────────────────────────────── */
.zone-grid { display: grid; grid-template-columns: repeat(auto-fill, minmax(250px, 1fr)); gap: 14px; max-width: 1240px; margin: 0 auto; }
.zone-card { position: relative; border-radius: 18px; overflow: hidden; min-height: 190px; border: 1px solid var(--line2); padding: 15px; display: flex; flex-direction: column; justify-content: flex-end; background: linear-gradient(165deg, var(--zc1), var(--zc2)); transition: .2s; cursor: pointer; }
.zone-card:hover { transform: translateY(-3px); border-color: rgba(255,209,102,.45); }
.zone-card::before { content: ''; position: absolute; inset: 0; background: linear-gradient(0deg, rgba(3,10,16,.85) 10%, rgba(3,10,16,.15) 65%, rgba(255,255,255,.06)); }
.zone-card.locked { filter: saturate(.35) brightness(.8); }
.zone-icon { position: absolute; top: 13px; left: 14px; font-size: 26px; color: #fff4d2; text-shadow: 0 2px 12px rgba(0,0,0,.5); z-index: 1; }
.zone-state { position: absolute; top: 15px; right: 14px; font-size: 9px; letter-spacing: .12em; padding: 4px 7px; border-radius: 6px; background: rgba(3,11,16,.6); border: 1px solid rgba(255,255,255,.15); color: #ffe6b1; z-index: 1; }
.zone-body { position: relative; z-index: 1; }
.zone-name { font-family: 'Cinzel'; font-size: 19px; color: #fff8e9; }
.zone-region { font-size: 9px; letter-spacing: .12em; color: rgba(255,255,255,.65); text-transform: uppercase; margin-bottom: 5px; }
.zone-desc { font-size: 10.5px; color: #bcd1d0; line-height: 1.45; margin-bottom: 9px; }
.zone-progress { display: flex; align-items: center; gap: 6px; font-size: 9px; color: #ffe5ac; }
.zone-progress .bar { flex: 1; height: 4px; }
.zone-progress .bar i { background: linear-gradient(90deg, var(--teal), var(--gold)); }
.zone-lock { position: absolute; inset: 0; z-index: 3; display: flex; flex-direction: column; align-items: center; justify-content: center; gap: 4px; background: rgba(3,10,15,.62); font-size: 10px; letter-spacing: .1em; color: #dbe7e5; }
.explore-note { max-width: 1240px; margin: 16px auto 0; font-size: 11px; color: var(--muted); }

/* ── village ────────────────────────────────────────────────────────────── */
.village-screen { display: flex; flex-direction: column; justify-content: space-between; overflow: hidden; }
.village-head { display: flex; align-items: flex-end; justify-content: space-between; gap: 14px; flex-wrap: wrap; }
.village-stats { display: flex; gap: 8px; flex-wrap: wrap; }
.stat-pill { display: flex; align-items: center; gap: 6px; padding: 7px 11px; border-radius: 99px; background: rgba(8,22,31,.7); border: 1px solid var(--line2); font-size: 10px; color: #d4e5e2; }
.stat-pill b { color: var(--gold); }
.village-rail { display: flex; gap: 11px; overflow-x: auto; padding: 4px 2px 8px; margin: 0 -2px; scrollbar-width: thin; scroll-snap-type: x mandatory; }
.build-card { flex: 0 0 196px; border-radius: 15px; border: 1px solid var(--line2); background: linear-gradient(165deg, rgba(13,34,45,.9), rgba(6,18,26,.9)); padding: 12px; scroll-snap-align: start; transition: .2s; backdrop-filter: blur(12px); }
.build-card:hover { border-color: rgba(255,209,102,.4); transform: translateY(-2px); }
.build-top { display: flex; align-items: center; gap: 9px; }
.build-icon { width: 36px; height: 36px; border-radius: 10px; display: grid; place-items: center; font-size: 17px; background: rgba(255,209,102,.09); border: 1px solid var(--line); color: var(--gold); }
.build-name { font-family: 'Cinzel'; font-size: 12px; color: #f8efda; }
.build-level { font-size: 8.5px; letter-spacing: .12em; color: var(--teal); text-transform: uppercase; }
.build-desc { font-size: 9.5px; color: var(--muted); line-height: 1.4; min-height: 40px; margin: 8px 0; }
.build-bonus { font-size: 9px; color: #ffe2a3; background: rgba(255,209,102,.06); border: 1px solid rgba(255,209,102,.14); border-radius: 6px; padding: 5px 6px; margin-bottom: 8px; }
.build-card .btn { width: 100%; padding: 7px; font-size: 10px; border-radius: 8px; }
.pips { display: flex; gap: 3px; }
.pips i { width: 14px; height: 4px; border-radius: 9px; background: rgba(255,255,255,.12); }
.pips i.on { background: var(--gold); }
.village-hint { text-align: center; font-size: 10px; color: rgba(255,255,255,.55); letter-spacing: .08em; margin-top: 6px; }

/* ── modal ──────────────────────────────────────────────────────────────── */
.modal-root { position: absolute; inset: 0; z-index: 60; display: grid; place-items: center; padding: 20px; background: rgba(2, 8, 12, .7); backdrop-filter: blur(8px); pointer-events: auto; animation: fadeIn .22s ease; }
.modal { width: min(560px, 94vw); max-height: 88dvh; overflow-y: auto; border-radius: 20px; border: 1px solid var(--line); background: linear-gradient(170deg, rgba(14,38,49,.98), rgba(5,17,24,.98)); box-shadow: 0 30px 90px rgba(0,0,0,.7); padding: 22px; animation: popIn .25s cubic-bezier(.2,.9,.3,1.2); scrollbar-width: thin; }
.modal h2 { font-size: 21px; color: #fff3d8; margin-bottom: 4px; }
.modal .modal-sub { font-size: 11.5px; color: var(--muted); line-height: 1.5; margin-bottom: 16px; }
.modal-close { position: absolute; top: 14px; right: 14px; }
.modal-actions { display: flex; gap: 8px; justify-content: flex-end; margin-top: 18px; flex-wrap: wrap; }
.opt-row { display: flex; align-items: center; justify-content: space-between; gap: 12px; padding: 11px 0; border-bottom: 1px solid rgba(255,255,255,.06); font-size: 12px; color: #d6e6e4; }
.opt-row small { display: block; font-size: 9.5px; color: var(--muted); margin-top: 2px; }
.seg { display: flex; gap: 3px; background: rgba(255,255,255,.05); border-radius: 9px; padding: 3px; }
.seg button { padding: 5px 9px; border-radius: 7px; font-size: 9.5px; font-weight: 800; color: #a3b8bb; }
.seg button.on { background: rgba(255,209,102,.17); color: var(--gold); }
.toggle { width: 42px; height: 24px; border-radius: 99px; background: rgba(255,255,255,.12); position: relative; transition: .2s; flex: none; }
.toggle::after { content: ''; position: absolute; top: 3px; left: 3px; width: 18px; height: 18px; border-radius: 50%; background: #d7e4e2; transition: .2s; }
.toggle.on { background: rgba(111,232,212,.5); }
.toggle.on::after { left: 21px; background: #fff; box-shadow: 0 0 10px rgba(111,232,212,.7); }
.building-modal-top { display: flex; gap: 12px; align-items: center; margin-bottom: 10px; }
.building-modal-top .build-icon { width: 52px; height: 52px; font-size: 25px; }
.bonus-table { display: flex; flex-direction: column; gap: 5px; margin: 10px 0; }
.bonus-line { display: flex; justify-content: space-between; font-size: 10.5px; padding: 6px 9px; border-radius: 7px; background: rgba(255,255,255,.03); color: #b5c9c8; }
.bonus-line.on { background: rgba(111,232,212,.08); color: var(--teal); }

/* ── HUD ────────────────────────────────────────────────────────────────── */
.hud { position: absolute; inset: 0; z-index: 18; pointer-events: none; }
.hud button, .hud .joystick, .hud .hud-panel { pointer-events: auto; }
.hud-top { position: absolute; top: calc(10px + var(--safe-top)); left: 50%; transform: translateX(-50%); display: flex; gap: 10px; align-items: flex-start; }
.hud-pos { display: flex; align-items: baseline; gap: 4px; font-family: 'Cinzel'; color: #fff5df; text-shadow: 0 2px 12px rgba(0,0,0,.65); }
.hud-pos .n { font-size: 32px; line-height: 1; color: var(--gold); font-weight: 900; }
.hud-pos .o { font-size: 11px; letter-spacing: .12em; color: #cfe0df; }
.hud-lapbox { text-align: center; padding: 6px 14px; border-radius: 11px; background: rgba(4,13,19,.58); border: 1px solid rgba(255,255,255,.1); backdrop-filter: blur(8px); }
.hud-lapbox .lap { font-family: 'Cinzel'; font-size: 13px; color: #fff1d3; letter-spacing: .1em; }
.hud-lapbox .timer { font-size: 15px; font-weight: 800; font-variant-numeric: tabular-nums; color: #fff; letter-spacing: .04em; margin-top: 1px; }
.hud-lapbox .label { font-size: 8px; letter-spacing: .18em; color: var(--muted); text-transform: uppercase; }
.hud-left { position: absolute; top: calc(14px + var(--safe-top)); left: clamp(10px, 2vw, 22px); display: flex; flex-direction: column; gap: 7px; }
.hud-chip { display: flex; align-items: center; gap: 6px; padding: 6px 10px; border-radius: 9px; background: rgba(4,13,19,.6); border: 1px solid rgba(255,255,255,.1); font-size: 10.5px; color: #dfeceb; backdrop-filter: blur(8px); }
.hud-chip b { color: var(--gold); font-weight: 900; }
.hud-chip.warn { border-color: rgba(255,123,140,.4); color: #ffc9d2; }
.timer-ring { position: relative; width: 40px; height: 40px; display: grid; place-items: center; }
.timer-ring svg { position: absolute; inset: 0; transform: rotate(-90deg); }
.timer-ring .val { font-size: 11px; font-weight: 900; color: var(--gold); }
.hud-right { position: absolute; top: calc(12px + var(--safe-top)); right: clamp(10px, 2vw, 22px); display: flex; flex-direction: column; align-items: flex-end; gap: 8px; }
.minimap-wrap { width: 128px; height: 128px; border-radius: 50%; background: rgba(4,13,19,.62); border: 1px solid rgba(255,255,255,.16); box-shadow: 0 8px 26px rgba(0,0,0,.35), inset 0 0 30px rgba(0,0,0,.3); overflow: hidden; position: relative; }
.minimap-wrap canvas { width: 100%; height: 100%; display: block; }
.minimap-label { position: absolute; bottom: 7px; left: 50%; transform: translateX(-50%); font-size: 7px; letter-spacing: .16em; color: rgba(255,240,200,.65); text-transform: uppercase; }
.pause-btn { width: 38px; height: 38px; border-radius: 11px; background: rgba(4,13,19,.62); border: 1px solid rgba(255,255,255,.14); color: #e8f2f0; font-size: 14px; display: grid; place-items: center; backdrop-filter: blur(8px); }
.hud-notices { position: absolute; top: 21%; left: 50%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 6px; width: min(90vw, 520px); }
.notice { padding: 8px 18px; border-radius: 99px; background: rgba(4,13,19,.74); border: 1px solid rgba(255,209,102,.35); color: #ffedc6; font-size: 12px; font-weight: 800; letter-spacing: .03em; animation: noticeIn .25s ease, noticeOut .4s ease 2.2s forwards; backdrop-filter: blur(8px); text-align: center; }
.notice.gate { border-color: rgba(111,232,212,.4); color: #c8fff6; }
.notice.warn { border-color: rgba(255,123,140,.45); color: #ffd3dc; }
.notice.elim { border-color: rgba(255,90,100,.6); color: #ffc0c8; background: rgba(50,8,14,.7); }
.notice.go { font-size: 20px; letter-spacing: .2em; border-color: var(--gold); background: rgba(50,35,8,.6); }
@keyframes noticeIn { from { opacity: 0; transform: translateY(-8px) scale(.96); } to { opacity: 1; } }
@keyframes noticeOut { to { opacity: 0; transform: translateY(-8px); } }

.countdown { position: absolute; inset: 0; display: grid; place-items: center; z-index: 5; pointer-events: none; }
.countdown .num { font-family: 'Cinzel'; font-size: clamp(90px, 22vw, 190px); font-weight: 900; color: #fff6dd; text-shadow: 0 0 40px rgba(255,209,102,.7), 0 10px 50px rgba(0,0,0,.6); animation: countPop .9s ease infinite; }
.countdown .num.small { font-size: clamp(46px, 10vw, 80px); letter-spacing: .18em; color: var(--gold); animation: countGo .6s ease; }
@keyframes countPop { 0% { transform: scale(1.35); opacity: 0; } 18% { transform: scale(1); opacity: 1; } 72% { transform: scale(.98); opacity: 1; } 100% { transform: scale(.9); opacity: .2; } }
@keyframes countGo { from { transform: scale(1.5); opacity: 0; } 30% { transform: scale(1); opacity: 1; } to { opacity: 0; } }

.hud-bottom { position: absolute; left: 0; right: 0; bottom: calc(14px + var(--safe-bottom)); padding: 0 clamp(12px, 2.5vw, 24px); display: flex; align-items: flex-end; justify-content: space-between; gap: 14px; }
.joystick {
  width: 118px; height: 118px; border-radius: 50%; position: relative; flex: none;
  background: radial-gradient(circle at 50% 45%, rgba(10,29,38,.5), rgba(4,13,19,.55));
  border: 1px solid rgba(255,255,255,.18); box-shadow: inset 0 0 30px rgba(0,0,0,.25);
  touch-action: none; backdrop-filter: blur(6px);
}
.joystick::before, .joystick::after { content: ''; position: absolute; background: rgba(255,255,255,.09); }
.joystick::before { left: 50%; top: 14%; bottom: 14%; width: 1px; }
.joystick::after { top: 50%; left: 14%; right: 14%; height: 1px; }
.joy-knob {
  position: absolute; width: 46px; height: 46px; border-radius: 50%; left: 50%; top: 50%;
  transform: translate(-50%, -50%); background: radial-gradient(circle at 35% 30%, #fff4d2, #ffc95a 50%, #c78528);
  border: 1px solid #fff2c7; box-shadow: 0 4px 18px rgba(0,0,0,.4), 0 0 20px rgba(255,190,80,.25);
  pointer-events: none;
}
.joy-hint { position: absolute; inset: 0; display: grid; place-items: center; font-size: 8px; letter-spacing: .2em; color: rgba(255,255,255,.3); text-transform: uppercase; pointer-events: none; }
.hud-speed { position: absolute; left: 50%; bottom: 0; transform: translateX(-42%); min-width: 190px; padding: 9px 15px 11px; border-radius: 14px; background: rgba(4,13,19,.55); border: 1px solid rgba(255,255,255,.1); backdrop-filter: blur(8px); }
.speed-line { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.speed-val { font-family: 'Cinzel'; font-size: 26px; font-weight: 900; color: #fff7e1; line-height: 1; font-variant-numeric: tabular-nums; }
.speed-unit { font-size: 8px; letter-spacing: .16em; color: var(--muted); }
.stamina-row { display: flex; align-items: center; gap: 6px; margin-top: 6px; }
.stamina-row .lab { font-size: 7px; letter-spacing: .14em; color: var(--muted); text-transform: uppercase; width: 30px; }
.stamina { flex: 1; height: 5px; border-radius: 9px; background: rgba(255,255,255,.1); overflow: hidden; }
.stamina i { display: block; height: 100%; border-radius: 9px; background: linear-gradient(90deg, var(--teal2), var(--teal)); box-shadow: 0 0 8px rgba(111,232,212,.6); transition: width .08s; }
.stamina.boosting i { background: linear-gradient(90deg, #ff9f43, var(--gold)); box-shadow: 0 0 10px rgba(255,180,80,.7); }
.speed-line .boost-tag { font-size: 8px; font-weight: 900; letter-spacing: .12em; color: var(--gold); opacity: 0; transition: .2s; }
.speed-line .boost-tag.on { opacity: 1; text-shadow: 0 0 10px rgba(255,209,102,.8); }
.action-cluster { display: grid; grid-template-columns: auto auto; grid-template-rows: auto auto; gap: 8px; align-items: end; justify-items: end; }
.action-btn {
  position: relative; border-radius: 50%; display: grid; place-items: center; text-align: center;
  background: radial-gradient(circle at 35% 30%, rgba(40,75,88,.9), rgba(8,23,31,.85));
  border: 1px solid rgba(255,255,255,.2); box-shadow: 0 8px 24px rgba(0,0,0,.35), inset 0 1px 0 rgba(255,255,255,.15);
  color: #eaf6f4; touch-action: none; transition: transform .1s, box-shadow .15s;
}
.action-btn:active, .action-btn.pressed { transform: scale(.94); }
.action-btn .ico { font-size: 22px; line-height: 1; }
.action-btn .lbl { font-size: 7px; letter-spacing: .1em; text-transform: uppercase; margin-top: 1px; opacity: .65; }
.action-btn.boost { width: 86px; height: 86px; background: radial-gradient(circle at 35% 30%, rgba(120,90,30,.9), rgba(38,25,6,.88)); border-color: rgba(255,209,102,.5); color: #ffe9b4; box-shadow: 0 8px 26px rgba(0,0,0,.4), 0 0 30px rgba(255,190,80,.18), inset 0 1px 0 rgba(255,255,255,.18); }
.action-btn.boost .ico { font-size: 27px; }
.action-btn.ability { width: 62px; height: 62px; border-color: rgba(111,232,212,.4); color: #c8fff6; }
.action-btn.ability.ready { box-shadow: 0 0 22px rgba(111,232,212,.35); }
.action-btn.ability .cool { position: absolute; inset: -1px; border-radius: 50%; background: conic-gradient(rgba(3,10,15,.8) var(--cd, 0%), transparent 0); }
.action-btn.ability .cd-text { position: absolute; inset: 0; display: grid; place-items: center; font-size: 15px; font-weight: 900; color: #fff; }
.action-btn.maneuver { width: 50px; height: 50px; border-color: rgba(177,138,255,.35); }
.action-btn.maneuver .ico { font-size: 17px; }
.action-btn.brake { width: 48px; height: 48px; border-color: rgba(255,123,169,.3); }
.action-btn.brake .ico { font-size: 16px; }
.action-btn.boost.off { opacity: .55; }
.action-btn.boost.on { box-shadow: 0 0 34px rgba(255,190,80,.5), inset 0 0 22px rgba(255,200,90,.25); border-color: var(--gold); }

.hud-hint { position: absolute; bottom: calc(146px + var(--safe-bottom)); left: 50%; transform: translateX(-50%); font-size: 9.5px; color: rgba(255,255,255,.55); letter-spacing: .06em; white-space: nowrap; text-align: center; }
.hud-objective { position: absolute; top: 18%; left: 50%; transform: translateX(-50%); display: flex; flex-direction: column; align-items: center; gap: 5px; font-size: 10px; color: #d8e9e7; letter-spacing: .06em; text-shadow: 0 2px 8px rgba(0,0,0,.6); }
.hud-objective b { color: var(--gold); }
.explore-prompt { position: absolute; left: 50%; bottom: calc(150px + var(--safe-bottom)); transform: translateX(-50%); display: flex; align-items: center; gap: 10px; padding: 10px 12px 10px 16px; border-radius: 14px; background: rgba(5,18,25,.9); border: 1px solid rgba(255,209,102,.55); box-shadow: 0 10px 40px rgba(0,0,0,.5), 0 0 30px rgba(255,209,102,.12); animation: promptIn .3s ease; pointer-events: auto; }
.explore-prompt .ep-icon { font-size: 25px; filter: drop-shadow(0 0 8px rgba(255,209,102,.5)); }
.explore-prompt .ep-text { display: flex; flex-direction: column; font-size: 10px; color: #ffe8b7; }
.explore-prompt .ep-text b { font-family: 'Cinzel'; font-size: 12px; }
.explore-prompt .ep-text span { font-size: 9px; color: #c4d7d5; }
@keyframes promptIn { from { opacity: 0; transform: translate(-50%, 10px); } }
.explore-exit { position: absolute; top: calc(12px + var(--safe-top)); right: clamp(10px, 2vw, 22px); display: flex; gap: 7px; }

/* ── toast ──────────────────────────────────────────────────────────────── */
.toast-root { position: absolute; left: 50%; top: calc(78px + var(--safe-top)); transform: translateX(-50%); z-index: 70; display: flex; flex-direction: column; gap: 7px; width: min(90vw, 380px); align-items: center; pointer-events: none; }
.toast { display: flex; align-items: center; gap: 9px; padding: 9px 15px; border-radius: 12px; background: rgba(6,20,27,.94); border: 1px solid rgba(255,209,102,.35); box-shadow: 0 10px 30px rgba(0,0,0,.45); font-size: 11.5px; color: #ffedca; animation: toastIn .3s ease, toastOut .4s ease 2.4s forwards; backdrop-filter: blur(10px); }
.toast .t-ico { font-size: 17px; color: var(--gold); }
.toast .t-sub { display: block; font-size: 9px; color: var(--muted); margin-top: 1px; }
.toast.good { border-color: rgba(111,232,212,.4); color: #d6fffa; }
.toast.good .t-ico { color: var(--teal); }
@keyframes toastIn { from { opacity: 0; transform: translateY(-10px); } }
@keyframes toastOut { to { opacity: 0; transform: translateY(-8px); } }

/* ── results ────────────────────────────────────────────────────────────── */
.results-wrap { position: absolute; inset: 0; z-index: 30; display: grid; place-items: center; padding: 20px; background: radial-gradient(ellipse at 50% 30%, rgba(30,60,72,.55), rgba(2,8,12,.88)); backdrop-filter: blur(6px); animation: fadeIn .3s ease; overflow-y: auto; }
.results { width: min(680px, 95vw); max-height: 94dvh; overflow-y: auto; border-radius: 24px; border: 1px solid var(--line); background: linear-gradient(170deg, rgba(13,36,47,.97), rgba(5,16,23,.98)); box-shadow: 0 40px 100px rgba(0,0,0,.7); padding: clamp(18px, 4vw, 32px); position: relative; scrollbar-width: thin; text-align: center; }
.results::before { content: ''; position: absolute; inset: 0; border-radius: 24px; background: radial-gradient(70% 60% at 50% 0%, rgba(255,209,102,.14), transparent 70%); pointer-events: none; }
.place-big { font-family: 'Cinzel'; font-size: clamp(52px, 11vw, 92px); line-height: .9; background: linear-gradient(180deg, #fff8e4, #ffd166 60%, #c9852d); -webkit-background-clip: text; background-clip: text; -webkit-text-fill-color: transparent; filter: drop-shadow(0 8px 30px rgba(255,190,80,.3)); position: relative; }
.place-big.lose { background: linear-gradient(180deg, #e8eef0, #9db4bc); -webkit-background-clip: text; background-clip: text; }
.result-kicker { font-size: 10px; letter-spacing: .3em; text-transform: uppercase; color: var(--teal); margin-bottom: 5px; position: relative; }
.result-title { font-family: 'Cinzel'; font-size: clamp(20px, 3.4vw, 30px); color: #fff4dd; margin-top: 2px; position: relative; }
.result-sub { font-size: 11px; color: var(--muted); margin: 5px 0 16px; }
.result-stats { display: grid; grid-template-columns: repeat(4, 1fr); gap: 7px; margin: 14px 0; position: relative; }
.rs { padding: 10px 6px; border-radius: 11px; background: rgba(255,255,255,.04); border: 1px solid var(--line2); }
.rs .k { font-size: 8px; letter-spacing: .12em; color: var(--muted); text-transform: uppercase; }
.rs .v { font-family: 'Cinzel'; font-size: 16px; color: #ffedc9; margin-top: 2px; font-variant-numeric: tabular-nums; }
.rs .v.gold { color: var(--gold); }
.standing-list { margin: 12px 0; position: relative; text-align: left; max-height: 200px; overflow-y: auto; scrollbar-width: thin; }
.standing-row { display: grid; grid-template-columns: 26px 1fr auto auto; gap: 8px; align-items: center; padding: 7px 9px; border-radius: 9px; font-size: 11px; color: #c6d8d7; border-bottom: 1px solid rgba(255,255,255,.045); }
.standing-row.me { background: rgba(255,209,102,.1); color: #fff2d4; border-radius: 9px; }
.standing-row .sp { font-family: 'Cinzel'; font-weight: 900; color: var(--gold); font-size: 11px; }
.standing-row .nm { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.standing-row .gap { font-size: 9px; color: var(--muted); }
.standing-row .out { font-size: 8.5px; color: #ff9aa8; letter-spacing: .08em; }
.rewards-row { display: flex; justify-content: center; gap: 8px; flex-wrap: wrap; margin: 13px 0; position: relative; }
.reward-chip { display: flex; align-items: center; gap: 6px; padding: 8px 13px; border-radius: 10px; background: rgba(255,209,102,.08); border: 1px solid rgba(255,209,102,.22); font-size: 12px; font-weight: 800; color: #ffe6ad; }
.reward-chip.gem { background: rgba(111,232,212,.07); border-color: rgba(111,232,212,.22); color: #c5fff8; }
.reward-chip.xp { background: rgba(177,138,255,.07); border-color: rgba(177,138,255,.22); color: #e3d3ff; }
.new-best { font-size: 10px; letter-spacing: .16em; text-transform: uppercase; color: var(--teal); margin-bottom: 8px; }
.results-actions { display: flex; gap: 8px; justify-content: center; flex-wrap: wrap; margin-top: 8px; position: relative; }
.champ-table { margin-top: 12px; padding: 10px; border-radius: 12px; background: rgba(255,255,255,.03); border: 1px solid var(--line2); }
.champ-table h4 { font-size: 11px; color: var(--gold); margin-bottom: 6px; letter-spacing: .1em; }
.champ-row { display: grid; grid-template-columns: 20px 1fr auto; gap: 7px; font-size: 10px; padding: 4px 0; color: #bfd2d1; }
.champ-row.me { color: var(--gold); font-weight: 800; }
.confetti { position: absolute; inset: 0; overflow: hidden; pointer-events: none; border-radius: 24px; }
.confetti i { position: absolute; width: 6px; height: 10px; top: -20px; opacity: .8; animation: confettiFall linear infinite; }
@keyframes confettiFall { to { transform: translateY(720px) rotate(540deg); opacity: 0; } }

/* ── misc ───────────────────────────────────────────────────────────────── */
.empty-state { text-align: center; padding: 40px 20px; color: var(--muted); font-size: 12px; }
.section-divider { height: 1px; background: linear-gradient(90deg, transparent, var(--line), transparent); margin: 16px 0; }
.fade-in { animation: fadeIn .35s ease both; }
@keyframes fadeIn { from { opacity: 0; } to { opacity: 1; } }
@keyframes popIn { from { opacity: 0; transform: scale(.94) translateY(8px); } to { opacity: 1; transform: none; } }
.rotate { position: absolute; inset: 0; z-index: 80; display: grid; place-items: center; background: rgba(3,10,15,.92); color: #ffeac2; text-align: center; padding: 30px; }
.rotate-icon { font-size: 50px; color: var(--gold); margin-bottom: 8px; }
.rotate p { max-width: 260px; color: var(--muted); font-size: 13px; line-height: 1.5; }
.fatal { position: absolute; inset: 0; z-index: 100; display: grid; place-items: center; background: #07121b; color: #ffd7b0; padding: 30px; text-align: center; font-size: 14px; line-height: 1.6; }

/* ── responsive ─────────────────────────────────────────────────────────── */
@media (max-width: 1120px) {
  .hangar-layout { grid-template-columns: 210px 1fr 350px; }
  .hub-grid { grid-template-columns: 1fr 330px; }
}
@media (max-width: 900px) {
  .menu-screen { grid-template-columns: minmax(280px, 420px) 1fr; }
  .menu-cards { display: none; }
  .menu-hero { grid-column: 1; }
  .hub-grid { grid-template-columns: 1fr; }
  .race-side { position: static; }
  .featured-strip { grid-template-columns: 1fr; }
  .hangar-layout { grid-template-columns: 1fr; height: auto; }
  .hangar-side { order: 2; }
  .hangar-center { order: 1; height: 34vh; min-height: 180px; }
  .hangar-panel { order: 3; max-height: none; }
  .dragon-list { flex-direction: row; overflow-x: auto; overflow-y: hidden; padding-bottom: 5px; }
  .dragon-row { flex: 0 0 170px; }
  .hangar-screen { overflow-y: auto; }
  .screen { padding-left: 14px; padding-right: 14px; }
  .minimap-wrap { width: 102px; height: 102px; }
}
@media (max-width: 700px) {
  .topbar { padding-top: calc(8px + var(--safe-top)); }
  .rider-name { max-width: 26vw; font-size: 11px; }
  .rider-avatar { width: 36px; height: 36px; font-size: 15px; }
  .xp-mini { width: 68px; }
  .currency { padding: 6px 9px; font-size: 11.5px; }
  .currency b { font-size: 11.5px; }
  .icon-btn { width: 34px; height: 34px; }
  .screen { padding-top: calc(66px + var(--safe-top)); padding-bottom: calc(78px + var(--safe-bottom)); }
  .menu-screen { display: flex; flex-direction: column; justify-content: space-between; gap: 16px; padding-bottom: calc(88px + var(--safe-bottom)); overflow-y: auto; }
  .menu-hero { align-self: stretch; padding-top: 8px; }
  .logo-main { font-size: clamp(42px, 13vw, 60px); }
  .logo-tag { font-size: 8px; letter-spacing: .32em; }
  .menu-blurb { font-size: 12px; margin: 12px 0 16px; max-width: 92%; }
  .hero-actions .btn { flex: 1; padding: 13px 12px; font-size: 12px; }
  .menu-cards { display: flex; max-width: 100%; width: 100%; }
  .active-dragon-strip { margin-top: 15px; }
  .bottomnav { width: calc(100% - 20px); justify-content: space-around; gap: 0; bottom: calc(8px + var(--safe-bottom)); border-radius: 18px; padding: 4px; }
  .nav-btn { min-width: 0; flex: 1; padding: 8px 4px; }
  .nav-btn .lbl { font-size: 7.5px; letter-spacing: .08em; }
  .nav-btn .ico { font-size: 17px; }
  .screen-head { margin-bottom: 13px; }
  .screen-title { font-size: 25px; }
  .screen-sub { font-size: 11.5px; }
  .track-grid { grid-template-columns: 1fr 1fr; gap: 8px; }
  .track-card { min-height: 122px; padding: 11px; }
  .track-name { font-size: 13px; }
  .track-icon { font-size: 18px; }
  .hub-grid { gap: 13px; }
  .side-panel { padding: 14px; }
  .mode-pills { gap: 5px; }
  .mode-pill { padding: 7px 10px; font-size: 10px; }
  .league-card { padding: 10px; }
  .shop-grid { grid-template-columns: repeat(2, 1fr); gap: 9px; }
  .zone-grid { grid-template-columns: 1fr 1fr; gap: 9px; }
  .zone-card { min-height: 165px; padding: 12px; }
  .zone-name { font-size: 15px; }
  .zone-desc { display: none; }
  .featured { padding: 15px; min-height: 130px; }
  .featured .f-title { font-size: 18px; }
  .village-head { align-items: flex-start; flex-direction: column; }
  .village-stats { gap: 5px; }
  .stat-pill { font-size: 9px; padding: 5px 8px; }
  .build-card { flex-basis: 168px; }
  .hangar-layout { gap: 12px; }
  .dragon-head { padding: 11px 13px 9px; }
  .dragon-title { font-size: 21px; }
  .tab-body { padding: 10px 13px 14px; }
  .tabs { padding: 0 4px; }
  .tab { padding: 9px 7px; font-size: 9px; }
  .cos-grid { grid-template-columns: repeat(3, 1fr); }
  .stat-line { grid-template-columns: 58px 1fr 26px 31px; font-size: 10px; }
  .hud-pos .n { font-size: 26px; }
  .hud-lapbox { padding: 5px 10px; }
  .hud-lapbox .timer { font-size: 13px; }
  .minimap-wrap { width: 88px; height: 88px; }
  .hud-speed { min-width: 140px; padding: 7px 10px; transform: translateX(-35%); }
  .speed-val { font-size: 20px; }
  .joystick { width: 102px; height: 102px; }
  .joy-knob { width: 40px; height: 40px; }
  .action-btn.boost { width: 76px; height: 76px; }
  .action-btn.ability { width: 56px; height: 56px; }
  .action-btn.maneuver { width: 45px; height: 45px; }
  .action-btn.brake { display: none; }
  .hud-speed { display: none; }
  .hud-hint { font-size: 8.5px; bottom: calc(126px + var(--safe-bottom)); }
  .hud-bottom { gap: 6px; }
  .result-stats { grid-template-columns: repeat(2, 1fr); }
  .modal { padding: 17px; }
  .toast-root { top: calc(66px + var(--safe-top)); }
  .explore-prompt { bottom: calc(132px + var(--safe-bottom)); }
}
@media (max-width: 420px) {
  .track-grid { grid-template-columns: 1fr; }
  .track-card { min-height: 108px; }
  .zone-grid { grid-template-columns: 1fr; }
  .zone-card { min-height: 145px; }
  .menu-cards .dailies-card { display: none; }
  .battle-hud { font-size: 10px; }
  .minimap-wrap { width: 76px; height: 76px; }
  .hud-pos .n { font-size: 23px; }
  .hud-lapbox { padding: 4px 8px; }
  .joystick { width: 92px; height: 92px; }
  .action-btn.boost { width: 70px; height: 70px; }
}
@media (orientation: portrait) and (max-height: 500px) {
  .menu-cards { display: none; }
}
@media (prefers-reduced-motion: reduce) {
  * { animation-duration: .01ms !important; animation-iteration-count: 1 !important; transition-duration: .01ms !important; }
}

