      <div class="result-sub">${r.trackName} · ${isChamp ? `Round ${r.round} of 3` : modeName}${r.newBest ? ' · new personal best!' : ''}</div>
      <div class="result-stats">
        <div class="rs"><div class="k">Time</div><div class="v gold">${fmtTime(r.time)}</div></div>
