        <div class="rs"><div class="k">Gates</div><div class="v">${r.gates}</div></div>
        <div class="rs"><div class="k">Best</div><div class="v">${fmtTime(r.best)}</div></div>
      </div>
      ${r.newBest ? `<div class="new-best">✦ Personal best recorded</div>` : ''}
