import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ headless: true, args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--disable-dev-shm-usage'] });
const page = await browser.newPage({ viewport: { width: 1280, height: 800 } });
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.waitForTimeout(5000);
console.log(await page.evaluate(() => {
  const q = (s) => document.querySelector(s);
  const box = (s) => { const e = q(s); if (!e) return null; const r = e.getBoundingClientRect(); return { x: r.x, y: r.y, w: r.width, h: r.height, opacity: getComputedStyle(e).opacity, anim: getComputedStyle(e).animationName, bg: getComputedStyle(e).backgroundImage.slice(0,80) }; };
  return {
    screen: box('#screen'), menu: box('.menu-screen'), hero: box('.menu-hero'), cards: box('.menu-cards'),
    logo: box('.logo-main'), event: box('.event-card'), before: (() => { const e = q('.menu-screen'); const c = getComputedStyle(e, '::before'); return { bg: c.backgroundImage.slice(0,120), z: c.zIndex, opacity: c.opacity }; })(),
    player: window.dragonGame?.player?.position.toArray(), cam: window.dragonGame?.camera?.position.toArray(), target: window.dragonGame?.cameraTarget?.toArray(),
  };
}));
await page.screenshot({ path: 'screenshots/menu-desktop.jpg', type: 'jpeg', quality: 75 });
await browser.close();

