import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({
  headless: true,
  args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--ignore-gpu-blocklist', '--disable-dev-shm-usage']
});
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1 });
const errors = [];
page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGEERROR:', e.message); });
page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE ERROR:', m.text()); });
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.locator('#boot').waitFor({ state: 'detached', timeout: 15000 }).catch(() => {});
await page.waitForTimeout(500);
console.log('boot gone:', await page.locator('#boot').count() === 0, 'mode:', await page.evaluate(() => window.dragonGame?.mode));

// ---------- race ----------
await page.click('[data-action="quick-race"]');
await page.waitForTimeout(1200);
console.log('after start:', await page.evaluate(() => ({ mode: window.dragonGame.mode, state: window.dragonGame.race?.state, track: window.dragonGame.race?.trackId, hud: document.querySelector('#hud')?.className })));
await page.screenshot({ path: 'screenshots/race-countdown.png', type: 'jpeg', quality: 72 });
await page.waitForTimeout(3200);
console.log('flying:', await page.evaluate(() => ({ state: window.dragonGame.race.state, time: +window.dragonGame.race.time.toFixed(2), speed: +window.dragonGame.flight.speed.toFixed(1), gate: window.dragonGame.race.nextGate, dist: +window.dragonGame.player.position.distanceTo(window.dragonGame.world.gates[0].pos).toFixed(1) })));
const before = await page.evaluate(() => window.dragonGame.player.position.toArray());
await page.evaluate(() => { window.dragonGame.input.boost = true; });
await page.waitForTimeout(1800);
const after = await page.evaluate(() => ({ pos: window.dragonGame.player.position.toArray(), speed: window.dragonGame.flight.speed, stamina: window.dragonGame.flight.stamina, boosting: window.dragonGame.flight.boosting }));
await page.evaluate(() => { window.dragonGame.input.boost = false; });
console.log('boost moved:', Math.hypot(after.pos[0] - before[0], after.pos[2] - before[2]).toFixed(1), 'speed', after.speed.toFixed(1), 'stamina', after.stamina.toFixed(1), 'boosting', after.boosting);
await page.screenshot({ path: 'screenshots/race-flight.png', type: 'jpeg', quality: 72 });

// ---------- finish race by visiting gates ----------
const gateInfo = await page.evaluate(() => ({ gates: window.dragonGame.world.gates.length, laps: window.dragonGame.race.totalLaps }));
console.log('gate info:', gateInfo);
await page.evaluate(() => { window.dragonGame.race.totalLaps = 1; });
for (let i = 0; i < gateInfo.gates + 3; i++) {
  const done = await page.evaluate(() => {
    const g = window.dragonGame;
    if (!g.race || g.race.ended) return true;
    const gate = g.world.gates[g.race.nextGate % g.world.gates.length];
    g.player.position.copy(gate.pos);
    g.flight.yaw = Math.atan2(-gate.tangent.x, -gate.tangent.z);
    return false;
  });
  if (done) break;
  await page.waitForTimeout(140);
}
await page.waitForTimeout(900);
console.log('race ended:', await page.evaluate(() => ({ ended: window.dragonGame.race?.ended, state: window.dragonGame.race?.state, lap: window.dragonGame.race?.lap, pos: window.dragonGame.race?.playerPos, view: window.dragonUI?.view, results: !!document.querySelector('.results-wrap') })));
console.log('results text:', (await page.locator('.results-wrap').innerText().catch(() => '')).slice(0, 300));
await page.screenshot({ path: 'screenshots/race-results.png', type: 'jpeg', quality: 72 });

// close results
const homeBtn = page.locator('.results-wrap [data-action="goto"][data-id="menu"]');
if (await homeBtn.count()) { await homeBtn.first().click(); } else { await page.evaluate(() => window.dragonUI.closeResults()); }
await page.waitForTimeout(700);
console.log('back to menu:', await page.evaluate(() => ({ mode: window.dragonGame.mode, view: window.dragonUI.view })));

// ---------- screens ----------
const shots = [['hangar', 'hangar'], ['village', 'village'], ['race', 'race-hub'], ['dragons', 'roster'], ['shop', 'market'], ['explore', 'explore']];
for (const [nav, name] of shots) {
  const btn = page.locator(`#bottomnav [data-action="goto"][data-id="${nav}"]`);
  if (await btn.count()) await btn.first().click();
  else await page.evaluate((v) => window.dragonUI.goto(v), nav);
  await page.waitForTimeout(1000);
  const info = await page.evaluate(() => ({ view: window.dragonUI.view, mode: window.dragonGame.mode, title: document.querySelector('#screen .screen-title, #screen .dragon-title, #screen .hangar-title')?.textContent || '', err: document.querySelector('#fatal:not(.hidden)')?.textContent || '' }));
  console.log(name, JSON.stringify(info));
  await page.screenshot({ path: `screenshots/${name}.png`, type: 'jpeg', quality: 72 });
}

// explore a zone
const zone = page.locator('[data-action="launch-explore"], [data-action="explore-zone"], .zone-card').first();
console.log('zone cards:', await page.locator('.zone-card').count());
if (await page.locator('.zone-card').count()) {
  await page.locator('.zone-card').first().click();
  await page.waitForTimeout(2000);
  console.log('explore launch:', await page.evaluate(() => ({ mode: window.dragonGame.mode, view: window.dragonUI.view, zone: window.dragonGame.explore?.zoneId, hud: !!document.querySelector('#hud:not(.hidden)') })));
  await page.screenshot({ path: 'screenshots/explore-flight.png', type: 'jpeg', quality: 72 });
}

// persistence
const save = await page.evaluate(() => JSON.parse(localStorage.getItem('dragon-rush-save-v1') || 'null'));
console.log('save:', save ? { coins: save.coins, riderXp: save.riderXp, dragons: Object.keys(save.dragons).length, races: save.stats?.races } : null);
console.log('ERRORS', errors.length, errors.slice(0, 8));
await browser.close();

