import { createRequire } from 'node:module';
import { join } from 'node:path';
const require = createRequire(join(process.env.HOME, '.local/share/omgithub-playwright/package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ headless: true, args: ['--use-angle=swiftshader', '--enable-unsafe-swiftshader', '--disable-dev-shm-usage'] });
const errors = [];
const page = await browser.newPage({ viewport: { width: 390, height: 844 }, deviceScaleFactor: 1, hasTouch: true, isMobile: true });
page.on('pageerror', (e) => { errors.push(e.message); console.log('PAGEERROR:', e.message); });
page.on('console', (m) => { if (m.type() === 'error') console.log('CONSOLE:', m.text()); });
await page.goto('http://localhost:3000/', { waitUntil: 'load' });
await page.evaluate(() => localStorage.clear());
await page.reload({ waitUntil: 'load' });
await page.waitForTimeout(2600);

const snap = async (label) => {
  const s = await page.evaluate(() => ({
    view: window.dragonUI.view,
    gameMode: window.dragonGame.mode,
    hud: !document.querySelector('#hud').classList.contains('hidden'),
    hudMode: window.dragonUI.hudMode,
    results: !!document.querySelector('.results-wrap'),
    champ: window.dragonUI.champ ? { round: window.dragonUI.champ.round, pts: window.dragonUI.champ.playerPoints } : null,
    coins: window.dragonUI.S.coins,
    league: window.dragonUI.S.leagues.hatchling || null,
    err: window.__err,
  }));
  console.log(label, JSON.stringify(s));
  return s;
};

// Enter championship via UI
await page.locator('#bottomnav [data-action="goto"][data-id="race"]').click();
await page.waitForTimeout(700);
await page.locator('[data-action="select-mode"][data-id="championship"]').click();
await page.waitForTimeout(400);
await page.locator('[data-action="pick-league"][data-id="hatchling"]').click();
await page.waitForTimeout(400);
await page.screenshot({ path: 'screenshots/champ-hub.png' });
await page.locator('[data-action="enter-champ"]').click();
await page.waitForTimeout(500);
await page.screenshot({ path: 'screenshots/champ-modal.png' });
await page.locator('[data-action="start-championship"]').click();
await page.waitForTimeout(4500);
await snap('race1-start');
await page.screenshot({ path: 'screenshots/champ-race1.png' });

// ability + manoeuvre while flying
await page.evaluate(() => {
  const g = window.dragonGame;
  g.race.state = 'flying';
  g.race.startedAt = performance.now() - 20000;
});
await page.locator('#ability-btn').click();
await page.waitForTimeout(250);
console.log('abilityCd', await page.evaluate(() => window.dragonGame.flight.abilityCd));
await page.locator('[data-action="use-maneuver"]').click();
await page.waitForTimeout(250);
console.log('maneuverCd', await page.evaluate(() => window.dragonGame.flight.maneuverCd));

for (let round = 1; round <= 3; round++) {
  await page.evaluate(() => { const g = window.dragonGame; if (g.race && g.race.state === 'flying') g.endRace('finish'); });
  await page.waitForTimeout(1400);
  await snap(`round${round}-results`);
  if (round < 3) {
    await page.locator('[data-action="next-champ"]').click();
    await page.waitForTimeout(4200);
    await snap(`round${round + 1}-start`);
  }
}
await page.screenshot({ path: 'screenshots/champ-round3-results.png' });
await page.locator('[data-action="finish-championship"]').click();
await page.waitForTimeout(900);
await snap('championship-final');
await page.screenshot({ path: 'screenshots/champ-final.png' });

// leave the final screen and confirm a normal race is no longer treated as championship
await page.locator('[data-action="goto"][data-id="race"]').first().click();
await page.waitForTimeout(700);
console.log('modeId after final:', await page.evaluate(() => window.dragonUI.modeId));
console.log('champ after final:', await page.evaluate(() => window.dragonUI.champ));
console.log('ERRORS:', errors.length, errors);
await browser.close();

