193: export function canUnlockSkill(id, skill) {
194:   const d = state.dragons[id];
195:   if (!d) return { ok: false, reason: 'No dragon.' };
196:   if (d.skills.includes(skill.id)) return { ok: false, reason: 'Already learned.' };
197:   if (skillPoints(id) < skill.cost) return { ok: false, reason: 'No skill points.' };
198:   if (d.level < skill.req) return { ok: false, reason: `Requires level ${skill.req}.` };
199:   const group = Object.values(SKILLS).find(g => g.some(s => s.id === skill.id));
200:   const prev = group[group.indexOf(skill) - 1];
201:   if (prev && !d.skills.includes(prev.id)) return { ok: false, reason: `Learn ${prev.name} first.` };
