15: const CYL = new THREE.CylinderGeometry(1, 1, 1, 6);
16: 
17: function mesh(geo, mat, pos = [0, 0, 0], scale = [1, 1, 1], rot = [0, 0, 0]) {
18:   const m = new THREE.Mesh(geo, mat);
19:   m.position.set(...pos); m.scale.set(...scale); m.rotation.set(...rot);
20:   return m;
21: }
22: function ellip(mat, pos, scale, rot) { return mesh(SPHERE, mat, pos, scale, rot); }
23: function cylBetween(a, b, r, mat) {
24:   const dir = new THREE.Vector3().subVectors(b, a);
25:   const len = dir.length();
26:   const m = new THREE.Mesh(CYL, mat);
27:   m.position.copy(a).addScaledVector(dir, 0.5);
28:   m.scale.set(r, len, r);
29:   m.quaternion.setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.normalize());
30:   return m;
31: }
32: 
33: function wingGeometry(span, sweep = 1) {
34:   const v = [
35:     0.02, 0.02, 0.25,        // 0 root front
36:     span * 0.33, 0.16, -0.02,// 1 elbow
37:     span, 0.34, 0.18,        // 2 tip
38:     span * 0.82, 0.02, 0.82, // 3 outer trailing
39:     span * 0.42, -0.04, 0.70,// 4 mid trailing
40:     0.04, 0.02, 0.62,        // 5 root rear
41:   ];
42:   const idx = [0, 1, 4, 0, 4, 5, 1, 2, 3, 1, 3, 4];
43:   const g = new THREE.BufferGeometry();
44:   g.setAttribute('position', new THREE.Float32BufferAttribute(v, 3));
45:   g.setIndex(idx); g.computeVertexNormals();
46:   return g;
47: }
48: 
49: function pickTint(palette, tint) {
50:   if (!tint) return palette;
51:   return { ...palette, ...tint };
52: }
53: 
54: // ── main dragon builder ─────────────────────────────────────────────────────
55: export function createDragon(defOrId, opts = {}) {
56:   const def = typeof defOrId === 'string' ? DRAGON_MAP[defOrId] : defOrId;
57:   const level = opts.level || 1;
58:   const cosmetics = opts.cosmetics || {};
59:   const skin = COSMETICS.skin.find(s => s.id === (cosmetics.skin || 'default'));
60:   const saddle = COSMETICS.saddle.find(s => s.id === (cosmetics.saddle || 'none'));
61:   const armour = COSMETICS.armour.find(s => s.id === (cosmetics.armour || 'none'));
62:   const wingsAcc = COSMETICS.wings.find(s => s.id === (cosmetics.wings || 'none'));
63:   const outfit = COSMETICS.outfit.find(s => s.id === (opts.outfitId || 'novice')) || COSMETICS.outfit[0];
64:   const pal = pickTint(def.palette, skin?.tint);
65:   const sh = def.shape;
66: 
67:   const group = new THREE.Group();
68:   group.userData.dragon = def;
69:   const rig = new THREE.Group(); // scaled body rig
70:   group.add(rig);
71: 
72:   const mats = {
73:     body: flat(pal.body, { roughness: 0.68 }),
74:     belly: flat(pal.belly, { roughness: 0.8 }),
75:     wing: flat(pal.wing, { roughness: 0.72, side: THREE.DoubleSide }),
76:     wing2: flat(new THREE.Color(pal.wing).lerp(new THREE.Color(pal.belly), 0.25), { roughness: 0.72, side: THREE.DoubleSide }),
77:     accent: flat(pal.accent, { roughness: 0.5, metalness: 0.15 }),
78:     horn: flat(pal.horn, { roughness: 0.42 }),
79:     eye: basic(pal.eye),
80:     dark: flat('#2a2530', { roughness: 0.6 }),
81:     gold: flat('#e8b45a', { roughness: 0.3, metalness: 0.65 }),
82:     leather: flat('#5b3c2a', { roughness: 0.85 }),
83:     cloth: flat(outfit.colors.tunic, { roughness: 0.9 }),
84:     trim: flat(outfit.colors.trim, { roughness: 0.6, metalness: 0.25 }),
85:     helm: flat(outfit.colors.helm, { roughness: 0.4, metalness: 0.5 }),
86:     skin: flat('#d9a57c', { roughness: 0.8 }),
87:     glow: basic(pal.accent, 0.85),
88:     membrane: new THREE.MeshBasicMaterial({ color: new THREE.Color(pal.accent), transparent: true, opacity: 0.18, side: THREE.DoubleSide, depthWrite: false, toneMapped: false }),
89:   };
90: 
91:   const B = sh.body, L = sh.legs;
92:   // ── torso ──
93:   const body = ellip(mats.body, [0, 0, 0], [0.62 * B, 0.56 * B, 1.25 * B]);
94:   rig.add(body);
95:   const belly = ellip(mats.belly, [0, -0.16 * B, 0.05], [0.48 * B, 0.4 * B, 1.0 * B]);
96:   rig.add(belly);
97:   // shoulder hump
98:   rig.add(ellip(mats.body, [0, 0.18 * B, -0.38 * B], [0.5 * B, 0.4 * B, 0.6 * B]));
99: 
100:   // ── neck & head ──
101:   const neck = new THREE.Group();
102:   neck.position.set(0, 0.16 * B, -0.9 * B);
103:   rig.add(neck);
104:   const neckSegs = [
105:     { p: [0, 0.08, -0.34], s: [0.34, 0.34, 0.42] },
106:     { p: [0, 0.22, -0.62], s: [0.29, 0.30, 0.38] },
107:     { p: [0, 0.4, -0.9], s: [0.25, 0.26, 0.34] },
108:   ];
109:   neckSegs.forEach((s, i) => neck.add(ellip(mats.body, [s.p[0] * sh.neck, s.p[1] * sh.neck, s.p[2] * sh.neck], [s.s[0] * sh.neck, s.s[1], s.s[2] * sh.neck])));
110:   const bellyNeck = ellip(mats.belly, [0, 0.12 * sh.neck, -0.58 * sh.neck], [0.18, 0.2, 0.3]);
111:   neck.add(bellyNeck);
112: 
113:   const head = new THREE.Group();
114:   head.position.set(0, 0.5 * sh.neck, -1.02 * sh.neck);
115:   neck.add(head);
116:   const hm = sh.head;
117:   head.add(ellip(mats.body, [0, 0, 0], [0.27 * hm, 0.25 * hm, 0.36 * hm]));
118:   // snout
119:   head.add(ellip(mats.body, [0, -0.07, -0.34], [0.19 * hm, 0.16 * hm, 0.28 * hm]));
120:   head.add(ellip(mats.belly, [0, -0.14, -0.35], [0.14 * hm, 0.09 * hm, 0.22 * hm]));
121:   // nostrils
122:   head.add(mesh(SPHERE, mats.dark, [0.09 * hm, -0.02, -0.55 * hm], [0.035, 0.03, 0.03]));
123:   head.add(mesh(SPHERE, mats.dark, [-0.09 * hm, -0.02, -0.55 * hm], [0.035, 0.03, 0.03]));
124:   // brow + eyes
125:   for (const sd of [-1, 1]) {
126:     head.add(ellip(mats.eye, [0.17 * sd * hm, 0.07, -0.19 * hm], [0.065, 0.07, 0.075]));
127:     head.add(ellip(mats.dark, [0.185 * sd * hm, 0.07, -0.16 * hm], [0.028, 0.062, 0.05]));
128:     head.add(ellip(mats.body, [0.17 * sd * hm, 0.16, -0.19 * hm], [0.13 * hm, 0.05, 0.12]));
129:     // jaw
130:     head.add(ellip(mats.body, [0.09 * sd * hm, -0.16, -0.2], [0.11, 0.06, 0.24]));
131:   }
132:   // horns
133:   const hornCount = sh.horns;
134:   const hornScale = 1 + Math.min(0.5, (level - 1) / 26);
135:   for (let i = 0; i < hornCount; i++) {
136:     const sd = i % 2 === 0 ? 1 : -1;
137:     const bx = (0.13 + (i >> 1) * 0.07) * sd;
138:     const h = mesh(CONE, mats.horn, [bx, 0.24 + (i >> 1) * 0.04, 0.06], [0.07 * hornScale, 0.42 * hornScale, 0.07 * hornScale], [0.55, 0, -0.35 * sd]);
139:     head.add(h);
140:   }
141:   // cheek fins
142:   head.add(mesh(CONE, mats.accent, [0.27, 0.02, 0.02], [0.05, 0.3, 0.12], [0, 0, -1.25]));
143:   head.add(mesh(CONE, mats.accent, [-0.27, 0.02, 0.02], [0.05, 0.3, 0.12], [0, 0, 1.25]));
144:   // crest fin
145:   if (sh.horns >= 2) {
146:     for (let i = 0; i < 3; i++) head.add(mesh(CONE, mats.accent, [0, 0.24, -0.08 + i * 0.13], [0.045, 0.16 - i * 0.02, 0.12], [0.8, 0, 0]));
147:   }
148: 
149:   // ── wings ──
150:   const wingSpan = 1.55 * sh.wings * (1 + Math.min(0.22, (level - 1) * 0.012));
151:   const wingGroups = [];
152:   for (const sd of [1, -1]) {
153:     const wg = new THREE.Group();
154:     wg.position.set(0.34 * sd * B, 0.26 * B, -0.34 * B);
155:     wg.scale.x = sd;
156:     rig.add(wg);
157:     wingGroups.push(wg);
158:     // membrane
159:     const wmGeo = wingGeometry(wingSpan); wmGeo.userData.dyn = true;
160:     const wm = new THREE.Mesh(wmGeo, mats.wing);
161:     wm.rotation.y = -0.14;
162:     wg.add(wm);
163:     const innerGeo = wingGeometry(wingSpan * 0.62); innerGeo.userData.dyn = true;
164:     const inner = new THREE.Mesh(innerGeo, mats.wing2);
165:     inner.rotation.y = -0.05; inner.position.y = 0.005;
166:     wg.add(inner);
167:     // bones
168:     const root = new THREE.Vector3(0.02, 0.02, 0.2);
169:     const elbow = new THREE.Vector3(wingSpan * 0.33, 0.16, -0.02);
170:     const tip = new THREE.Vector3(wingSpan, 0.34, 0.18);
171:     wg.add(cylBetween(root, elbow, 0.055, mats.horn));
172:     wg.add(cylBetween(elbow, tip, 0.042, mats.horn));
173:     wg.add(cylBetween(elbow, new THREE.Vector3(wingSpan * 0.82, 0.02, 0.82), 0.025, mats.horn));
174:     wg.add(ellip(mats.horn, [elbow.x, elbow.y, elbow.z], [0.08, 0.08, 0.08]));
175:     // claw at tip
176:     wg.add(mesh(CONE, mats.horn, [wingSpan + 0.05, 0.36, 0.18], [0.05, 0.22, 0.05], [0, 0, -1.3]));
177:     // wing accessories
178:     if (wingsAcc?.id === 'ribbons') {
179:       for (let i = 0; i < 3; i++) {
180:         const rib = mesh(BOX, i % 2 ? mats.cloth : mats.trim, [0.5 + i * 0.3, 0.06, 0.55 + i * 0.1], [0.04, 0.3, 0.02], [0, 0.3, 0.4]);
181:         rib.userData.ribbon = true; rib.userData.phase = i * 1.7;
182:         wg.add(rib);
183:       }
184:     }
185:     if (wingsAcc?.id === 'blades') {
186:       wg.add(mesh(CONE, mats.gold, [wingSpan * 0.82, 0.18, 0.1], [0.08, 0.7, 0.18], [0.2, 0, -1.9]));
187:     }
188:     if (wingsAcc?.id === 'stars') {
189:       for (let i = 0; i < 5; i++) {
190:         const st = mesh(SPHERE, mats.glow, [0.5 + i * 0.28, 0.12 + Math.sin(i) * 0.08, 0.4 + i * 0.08], [0.035, 0.035, 0.035]);
191:         wg.add(st);
192:       }
193:     }
194:   }
195: 
196:   // ── tail ──
197:   const tailRoot = new THREE.Group();
198:   tailRoot.position.set(0, 0.1 * B, 1.05 * B);
199:   rig.add(tailRoot);
200:   const tailSegs = [];
201:   let parent = tailRoot;
202:   const segCount = 7;
203:   for (let i = 0; i < segCount; i++) {
204:     const seg = new THREE.Group();
205:     seg.position.z = i === 0 ? 0.08 : 0.34 * sh.tail;
206:     parent.add(seg);
207:     const s = 0.32 * B * (1 - i / (segCount + 1.6));
208:     seg.add(ellip(mats.body, [0, 0, 0.1], [s, s * 0.9, 0.34 * sh.tail]));
209:     if (i % 2 === 0 && i < 4) seg.add(mesh(CONE, mats.accent, [0, s * 0.75, 0.08], [0.05, 0.2, 0.16], [0.35, 0, 0]));
210:     tailSegs.push(seg);
211:     parent = seg;
212:   }
213:   // tail fin
214:   const finGeo = wingGeometry(0.75, 1); finGeo.userData.dyn = true;
215:   const fin = new THREE.Mesh(finGeo, mats.wing);
216:   fin.position.set(0, 0.02, 0.28); fin.rotation.set(1.35, 0.1, 0.5); fin.scale.set(0.9, 1, 1);
217:   parent.add(fin);
218:   const fin2 = fin.clone(); fin2.rotation.z = -0.5; fin2.scale.x = -0.9; parent.add(fin2);
219:   tailRoot.add(mesh(CONE, mats.accent, [0, 0.26, 0.9 * sh.tail], [0.04, 0.26, 0.2], [1.2, 0, 0]));
220: 
221:   // ── legs ──
222:   const legPositions = [
223:     [0.34, -0.28, -0.48], [-0.34, -0.28, -0.48],
224:     [0.38, -0.3, 0.5], [-0.38, -0.3, 0.5],
225:   ];
226:   for (const [x, y, z] of legPositions) {
227:     const leg = new THREE.Group();
228:     leg.position.set(x * B, y, z); rig.add(leg);
229:     leg.add(ellip(mats.body, [0.02, -0.1, 0], [0.15 * L, 0.24 * L, 0.17 * L]));
230:     leg.add(ellip(mats.dark, [0.03, -0.32, -0.04], [0.1 * L, 0.1 * L, 0.16 * L], [0.4, 0, 0]));
231:     leg.add(mesh(CONE, mats.horn, [0.05, -0.33, -0.17], [0.035, 0.13, 0.035], [-1.6, 0, 0]));
232:   }
233: 
234:   // ── spine spikes ──
235:   for (let i = 0; i < 6; i++) {
236:     const z = -0.7 + i * 0.27;
237:     const s = sh.spikes * (0.16 - i * 0.012);
238:     if (s > 0.02) rig.add(mesh(CONE, mats.accent, [0, 0.5 * B - i * 0.02, z * B], [s * 0.55, s * 2.4, s], [0.42, 0, 0]));
239:   }
240: 
241:   // ── markings ──
242:   const markings = new THREE.Group();
243:   rig.add(markings);
244:   if (sh.pattern === 'stripes' || sh.pattern === 'streaks') {
245:     for (let i = 0; i < 5; i++) {
246:       const z = -0.8 + i * 0.4;
247:       const stripe = ellip(mats.accent, [0, 0.36 * B, z], [0.34 * B, 0.05, 0.05], [0, 0, 0]);
248:       mats.accent.emissive = new THREE.Color(pal.accent); mats.accent.emissiveIntensity = 0.18;
249:       markings.add(stripe);
250:     }
251:     if (sh.pattern === 'streaks') {
252:       for (const sd of [-1, 1]) markings.add(ellip(mats.accent, [0.5 * sd * B, 0.06, 0.2], [0.03, 0.09, 0.5]));
253:     }
254:   } else if (sh.pattern === 'scales') {
255:     for (let i = 0; i < 8; i++) {
256:       const sd = i % 2 ? 1 : -1;
257:       markings.add(ellip(mats.accent, [0.47 * sd * B, 0.1 + (i % 3) * 0.08, -0.6 + Math.floor(i / 2) * 0.42], [0.07, 0.04, 0.11]));
258:     }
259:   } else if (sh.pattern === 'spots') {
260:     for (let i = 0; i < 9; i++) {
261:       const sd = i % 2 ? 1 : -1;
262:       markings.add(ellip(mats.accent, [0.4 * sd * B, 0.24 - (i % 3) * 0.1, -0.65 + (i >> 1) * 0.36], [0.11, 0.06, 0.13]));
263:     }
264:   } else if (sh.pattern === 'glow' || sh.pattern === 'lava' || sh.pattern === 'stars' || sh.pattern === 'prism') {
265:     const gm = new THREE.MeshBasicMaterial({ color: new THREE.Color(pal.accent), transparent: true, opacity: 0.85, toneMapped: false });
266:     for (let i = 0; i < 7; i++) {
267:       const sd = i % 2 ? 1 : -1;
268:       const line = mesh(BOX, gm, [0.52 * sd * B, 0.12 + (i % 3) * 0.07, -0.65 + Math.floor(i / 2) * 0.38], [0.02, 0.03, 0.24], [0, 0, 0.2 * sd]);
269:       markings.add(line);
270:     }
271:     if (sh.pattern === 'stars' || sh.pattern === 'prism') {
272:       for (let i = 0; i < 12; i++) {
273:         const sd = i % 2 ? 1 : -1;
274:         markings.add(mesh(SPHERE, mats.glow, [0.42 * sd * B, 0.22 + (i % 4) * 0.09, -0.7 + Math.floor(i / 2) * 0.24], [0.028, 0.028, 0.028]));
275:       }
276:     }
277:     if (sh.pattern === 'lava') {
278:       mats.body.emissive = new THREE.Color(pal.body); mats.body.emissiveIntensity = 0.13;
279:     }
280:   }
281: 
282:   // ── saddle + rider ──
283:   if (saddle && saddle.id !== 'none') {
284:     const sm = saddle.id === 'crown' ? mats.gold : saddle.id === 'silver' ? flat('#c9d3dd', { metalness: 0.7, roughness: 0.25 }) : mats.leather;
285:     const seat = ellip(sm, [0, 0.55 * B, 0.18], [0.42, 0.1, 0.4]);
286:     rig.add(seat);
287:     rig.add(mesh(BOX, sm, [0, 0.62, 0.08], [0.34, 0.07, 0.26], [0, 0, 0]));
288:     const strapGeo = new THREE.TorusGeometry(0.62 * B, 0.045, 4, 14); strapGeo.userData.dyn = true;
289:     const strap = new THREE.Mesh(strapGeo, sm);
290:     strap.rotation.x = Math.PI / 2; strap.scale.z = 1.0; strap.position.set(0, 0.05, 0.18);
291:     rig.add(strap);
292:   }
293:   // simple rider always present for race/hangar; can be hidden for wild dragons
294:   if (opts.rider !== false) {
295:     const rider = new THREE.Group();
296:     rider.position.set(0, 0.62 * B + (saddle?.id !== 'none' ? 0.12 : 0), 0.12);
297:     rig.add(rider);
298:     // legs
299:     rider.add(ellip(mats.cloth, [0.32, -0.14, 0.04], [0.11, 0.32, 0.15], [0.3, 0, 0.12]));
300:     rider.add(ellip(mats.cloth, [-0.32, -0.14, 0.04], [0.11, 0.32, 0.15], [0.3, 0, -0.12]));
301:     rider.add(ellip(mats.leather, [0.33, -0.4, 0.12], [0.11, 0.11, 0.19]));
302:     rider.add(ellip(mats.leather, [-0.33, -0.4, 0.12], [0.11, 0.11, 0.19]));
303:     // torso
304:     rider.add(ellip(mats.cloth, [0, 0.16, 0.02], [0.24, 0.38, 0.22], [0.12, 0, 0]));
305:     rider.add(ellip(mats.trim, [0, 0.42, 0.02], [0.24, 0.06, 0.23]));
306:     // arms
307:     rider.add(cylBetween(new THREE.Vector3(0.2, 0.32, 0), new THREE.Vector3(0.28, 0.06, -0.26), 0.06, mats.cloth));
308:     rider.add(cylBetween(new THREE.Vector3(-0.2, 0.32, 0), new THREE.Vector3(-0.28, 0.06, -0.26), 0.06, mats.cloth));
309:     // head + helmet
310:     rider.add(ellip(mats.skin, [0, 0.6, -0.02], [0.16, 0.18, 0.16]));
311:     rider.add(mesh(CONE, mats.helm, [0, 0.72, 0.0], [0.17, 0.18, 0.17], [0, 0, 0]));
312:     rider.add(mesh(BOX, mats.helm, [0.14, 0.62, -0.06], [0.04, 0.16, 0.12], [0, 0, -0.1]));
313:     rider.add(mesh(BOX, mats.helm, [-0.14, 0.62, -0.06], [0.04, 0.16, 0.12], [0, 0, 0.1]));
314:     // scarf
315:     const scarf = mesh(BOX, mats.trim, [0, 0.5, 0.15], [0.3, 0.08, 0.06]);
316:     scarf.userData.scarf = true; rider.add(scarf);
317:     // shoulder guard
318:     rider.add(ellip(mats.leather, [0.24, 0.4, -0.02], [0.11, 0.09, 0.16]));
319:     rider.add(ellip(mats.leather, [-0.24, 0.4, -0.02], [0.11, 0.09, 0.16]));
320:     rider.userData.baseY = rider.position.y;
321:     rig.add(rider);
322:     group.userData.rider = rider;
323:   }
324: 
325:   // ── armour cosmetic ──
326:   if (armour && armour.id !== 'none') {
327:     const am = armour.id === 'gold' ? mats.gold : armour.id === 'crystal' ? flat('#b8ecff', { roughness: 0.15, metalness: 0.3, emissive: '#5cc6e8', emissiveIntensity: 0.18 }) : flat('#6d747e', { roughness: 0.42, metalness: 0.7 });
328:     rig.add(ellip(am, [0, 0.4 * B, -0.3], [0.46, 0.16, 0.36]));
329:     for (const sd of [-1, 1]) {
330:       rig.add(ellip(am, [0.34 * sd, 0.5 * B, -0.3], [0.2, 0.12, 0.3], [0, 0, 0.25 * sd]));
331:       rig.add(mesh(CONE, am, [0.36 * sd, 0.68 * B, -0.32], [0.07, 0.25, 0.07], [0, 0, -0.4 * sd]));
332:     }
333:     // forehead plate
334:     head.add(ellip(am, [0, 0.2, -0.12], [0.18, 0.06, 0.22]));
335:   }
336: 
337:   // level aura: subtle glow halo
338:   if (level >= 6) {
339:     const haloGeo = new THREE.RingGeometry(1.6, 1.76, 32); haloGeo.userData.dyn = true;
340:     const halo = new THREE.Mesh(haloGeo, new THREE.MeshBasicMaterial({
341:       color: new THREE.Color(pal.accent), transparent: true, opacity: 0.18, side: THREE.DoubleSide, depthWrite: false, toneMapped: false,
342:     }));
343:     halo.rotation.x = -Math.PI / 2; halo.position.y = -0.7;
344:     group.userData.halo = halo; group.add(halo);
345:   }
346: 
347:   group.userData.rig = rig;
348:   group.userData.neck = neck;
349:   group.userData.head = head;
350:   group.userData.tailSegs = tailSegs;
351:   group.userData.wingGroups = wingGroups;
352:   group.userData.mats = mats;
353:   group.userData.pal = pal;
354:   group.userData.def = def;
