.side-title { display: flex; align-items: center; justify-content: space-between; margin-bottom: 2px; }
.side-title h2 { font-size: 15px; color: #fff1d4; }
.side-title span { font-size: 10px; color: var(--muted); }
.dragon-list { overflow-y: auto; display: flex; flex-direction: column; gap: 7px; padding-right: 4px; scrollbar-width: thin; }
.dragon-row {
  display: flex; align-items: center; gap: 9px; padding: 7px; border-radius: 12px; border: 1px solid transparent;
  background: rgba(9,23,32,.6); cursor: pointer; transition: .18s; text-align: left;
}
.dragon-row:hover { background: rgba(20,44,55,.7); border-color: var(--line2); }
