.dragon-row .nm { font-family: 'Cinzel'; font-size: 12px; color: #f7eedb; line-height: 1.1; }
.dragon-row .sub { font-size: 9px; color: var(--muted); margin-top: 2px; display: flex; align-items: center; gap: 5px; }
.rarity-dot { width: 5px; height: 5px; border-radius: 50%; display: inline-block; }
.dragon-row .lvl { margin-left: auto; font-size: 9.5px; font-weight: 800; color: var(--gold); background: rgba(255,209,102,.08); padding: 3px 5px; border-radius: 5px; }
.locked-row { opacity: .55; }
.locked-row .lock { margin-left: auto; font-size: 12px; }
.hangar-center { position: relative; pointer-events: none; display: flex; align-items: flex-end; justify-content: center; padding-bottom: 14px; }
.hangar-center .stage-hint { pointer-events: none; font-size: 10px; color: rgba(255,255,255,.5); letter-spacing: .12em; text-transform: uppercase; background: rgba(4,13,19,.4); padding: 6px 12px; border-radius: 99px; }
.hangar-panel {
  display: flex; flex-direction: column; min-height: 0; border: 1px solid var(--line); border-radius: 20px;
  background: linear-gradient(170deg, rgba(11,29,39,.93), rgba(5,16,23,.9)); backdrop-filter: blur(16px);
  box-shadow: var(--shadow); overflow: hidden;
}
