.dragon-rarity { display: inline-flex; align-items: center; gap: 5px; font-size: 8.5px; letter-spacing: .18em; text-transform: uppercase; font-weight: 900; color: var(--rarity, var(--gold)); margin-bottom: 4px; }
.dragon-rarity::before { content: '◆'; font-size: 8px; }
.dragon-title { font-family: 'Cinzel'; font-size: 24px; color: #fff7e3; line-height: 1.05; }
.dragon-epithet { font-size: 10.5px; color: var(--teal); letter-spacing: .06em; margin-top: 3px; }
.level-row { display: flex; align-items: center; gap: 9px; margin-top: 10px; }
.level-badge { font-size: 10px; font-weight: 900; color: #2a1c08; background: linear-gradient(140deg, #ffe39a, #eda438); padding: 4px 8px; border-radius: 6px; }
.level-xp { flex: 1; }
.level-xp .bar { height: 5px; }
.level-xp .txt { font-size: 9px; color: var(--muted); margin-top: 3px; display: flex; justify-content: space-between; }
.bond-box { padding: 10px 16px; border-bottom: 1px solid var(--line2); }
