.bond-actions { display: flex; gap: 5px; margin-top: 8px; }
.bond-actions button { flex: 1; padding: 7px 4px; border-radius: 8px; background: rgba(255,255,255,.05); border: 1px solid var(--line2); font-size: 9.5px; font-weight: 800; color: #dbe9e8; display: flex; flex-direction: column; align-items: center; gap: 2px; transition: .18s; }
