356:   const tmp = { flap: Math.random() * 6, t: 0 };
357:   let glide = 0;
358: 
359:   function update(dt, st = {}) {
360:     tmp.t += dt;
361:     tmp.flap += dt * (st.flapSpeed ?? (st.boosting ? 9 : 6));
362:     const speed = st.speed ?? 45;
363:     const flying = st.flying !== false;
364:     const glideTarget = st.gliding ? 1 : 0;
365:     glide += (glideTarget - glide) * Math.min(1, dt * 4);
366:     const flapAmt = flying ? (0.55 - glide * 0.35) : 0.0;
367:     const flap = Math.sin(tmp.flap) * flapAmt;
368:     const flap2 = Math.sin(tmp.flap + 0.4) * flapAmt * 0.8;
369:     wingGroups[0].rotation.z = 0.12 + flap;
370:     wingGroups[1].rotation.z = 0.12 + flap;
371:     wingGroups[0].rotation.y = -0.18 - flap2 * 0.22 + (st.bank || 0) * 0.06;
372:     wingGroups[1].rotation.y = 0.18 + flap2 * 0.22 + (st.bank || 0) * 0.06;
373:     // body bob + pitch lean
374:     rig.position.y = Math.sin(tmp.t * 2.1) * 0.05 * (flying ? 1 : 0.2);
375:     rig.rotation.x = (st.pitchLean || 0) * 0.25;
376:     rig.rotation.z = (st.bank || 0) * 0.25;
377:     // tail weave
378:     tailSegs.forEach((s, i) => {
379:       s.rotation.y = Math.sin(tmp.t * 3.1 + i * 0.6) * (0.05 + i * 0.01) * (0.5 + speed / 90);
380:       s.rotation.x = Math.sin(tmp.t * 2.2 + i * 0.5) * 0.02;
381:     });
382:     // neck sway & head look
383:     neck.rotation.x = Math.sin(tmp.t * 1.6) * 0.025 + (st.pitchLean || 0) * -0.2;
384:     neck.rotation.y = (st.headTurn || 0) * 0.16;
385:     head.rotation.x = Math.sin(tmp.t * 1.2) * 0.04;
386:     // rider bob and scarf flutter
387:     const rider = group.userData.rider;
388:     if (rider) {
389:       rider.position.y = rider.userData.baseY + Math.sin(tmp.t * 2.1 + 1) * 0.035;
390:       const sc = rider.children.find(c => c.userData.scarf);
391:       if (sc) sc.rotation.x = 0.2 + Math.sin(tmp.t * 8) * 0.15 + speed / 260;
392:     }
393:     wingGroups.forEach((wg, wi) => {
394:       wg.children.forEach(c => {
395:         if (c.userData.ribbon) {
396:           c.rotation.x = 0.3 + Math.sin(tmp.t * 5 + c.userData.phase) * 0.4;
397:           c.rotation.z = (wi ? -1 : 1) * (0.3 + Math.sin(tmp.t * 3 + c.userData.phase) * 0.2);
398:         }
399:       });
400:     });
401:     if (group.userData.halo) {
402:       group.userData.halo.rotation.z += dt * 0.4;
403:       group.userData.halo.material.opacity = 0.12 + Math.sin(tmp.t * 2) * 0.04;
404:       group.userData.halo.position.y = -0.72 - (st.wingWOsc || 0) * 0.3;
405:     }
406:     // banking aileron: flex the wing on the inside of the turn
407:     if (st.bank) {
408:       const b = THREE.MathUtils.clamp(st.bank, -1, 1);
409:       wingGroups[0].rotation.z += b * 0.10;
410:       wingGroups[1].rotation.z += b * 0.10;
411:     }
412:     // idle walking: leg sway? subtle
413:     mats.eye.color.set(pal.eye);
414:   }
