thumb(def, silhouette = false) {
  const key = silhouette ? def.id + ':sil' : def.id;
  if (!this.thumbs.has(key)) this.thumbs.set(key, dragonThumb(def, 128, silhouette));
  return this.thumbs.get(key);
}

