import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const url = 'http://localhost:3210/';
const out = '/tmp/opencode/shots';
const fs = await import('node:fs');
fs.mkdirSync(out, { recursive: true });

const browser = await chromium.launch({ args: ['--use-gl=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });
const results = [];
for (const [name, width, height] of [['desktop', 1440, 900], ['mobile', 390, 844]]) {
  const page = await browser.newPage({ viewport: { width, height } });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  await page.goto(url, { waitUntil: 'load', timeout: 60000 });
  await page.waitForFunction(() => !document.getElementById('boot'), null, { timeout: 30000 }).catch(() => {});
  await page.waitForTimeout(1200);

  // go to Dragons
  await page.click('[data-action="goto"][data-id="hangar"]');
  await page.waitForTimeout(1800);
  await page.screenshot({ path: `${out}/hangar-${name}.png` });

  // counts
  const info = await page.evaluate(() => ({
    chips: document.querySelectorAll('.habitat-chip').length,
    rows: document.querySelectorAll('.dragon-row').length,
    title: document.querySelector('.dragon-title')?.textContent,
    badge: document.querySelector('.habitat-badge')?.textContent?.trim(),
    hint: document.querySelector('.stage-hint')?.textContent,
    mode: window.dragonGame?.mode,
    ambient: window.dragonGame?.hangarAmbient?.length,
    err: document.getElementById('fatal')?.textContent,
  }));
  results.push({ name, info });

  // click the ice habitat chip
  const ice = page.locator('.habitat-chip', { hasText: 'Ice' }).first();
  if (await ice.count()) {
    await ice.click();
    await page.waitForTimeout(1400);
    await page.screenshot({ path: `${out}/hangar-ice-${name}.png` });
    results.push({ name, afterFilter: await page.evaluate(() => ({
      activeChip: document.querySelector('.habitat-chip.active')?.textContent?.trim(),
      rows: document.querySelectorAll('.dragon-row').length,
      focus: window.dragonGame?.hangarFocus,
      cameraTarget: window.dragonGame?.hangarTarget?.toArray?.().map(n => +n.toFixed(1)),
    })) });
  }

  // training ring visit
  const train = page.locator('[data-action="hangar-visit"][data-id="training"]');
  if (await train.count()) {
    await train.click();
    await page.waitForTimeout(1200);
    await page.screenshot({ path: `${out}/hangar-training-${name}.png` });
    results.push({ name, afterTrain: await page.evaluate(() => window.dragonGame?.hangarFocus) });
  }

  // all roosts
  await page.locator('.habitat-chip', { hasText: 'All roosts' }).first().click();
  await page.waitForTimeout(600);

  // back to market and check species filter
  await page.click('[data-action="goto"][data-id="shop"]');
  await page.waitForTimeout(1400);
  const shopChips = await page.locator('.habitat-chip').count();
  const shopCards = await page.locator('.shop-card').count();
  results.push({ name, shop: { chips: shopChips, cards: shopCards } });
  await page.screenshot({ path: `${out}/shop-${name}.png` });

  // pick fire filter in shop
  const fire = page.locator('.habitat-chip', { hasText: 'Fire' }).last();
  if (await fire.count()) {
    await fire.click();
    await page.waitForTimeout(600);
    results.push({ name, shopFireCards: await page.locator('.shop-card').count() });
  }

  if (errors.length) results.push({ name, errors: errors.slice(0, 10) });
  await page.close();
}
await browser.close();
console.log(JSON.stringify(results, null, 2));

