import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ args: ['--use-gl=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });

await page.goto('http://localhost:3210/', { waitUntil: 'load' });
await page.waitForFunction(() => !document.getElementById('boot'), null, { timeout: 30000 }).catch(() => {});
await page.waitForTimeout(1000);
const out = {};

await page.click('[data-action="goto"][data-id="hangar"]');
await page.waitForTimeout(1400);

// coins + bond before feed
out.before = await page.evaluate(() => ({ coins: window.dragonUI.S.coins, bond: window.dragonUI.S.dragons[window.dragonUI.dragonId].bond }));
await page.locator('.bond-actions button', { hasText: 'Feed' }).click();
await page.waitForTimeout(700);
out.afterFeed = await page.evaluate(() => ({ coins: window.dragonUI.S.coins, bond: window.dragonUI.S.dragons[window.dragonUI.dragonId].bond, react: window.dragonGame.hangarReact, toast: document.querySelector('.toast')?.textContent?.trim() }));

// 3D tap a habitat pad
const firePt = await page.evaluate(() => {
  const g = window.dragonGame;
  const a = g.world.anchors.find(x => x.family === 'fire');
  const v = a.position.clone(); v.y += 1.2;
  v.project(g.camera);
  return { x: (v.x * 0.5 + 0.5) * innerWidth, y: (-v.y * 0.5 + 0.5) * innerHeight };
});
await page.mouse.click(firePt.x, firePt.y);
await page.waitForTimeout(1000);
out.tapHabitat = await page.evaluate(() => ({ focus: window.dragonGame.hangarFocus, active: document.querySelector('.habitat-chip.active')?.textContent?.trim(), toast: document.querySelector('.toast')?.textContent?.trim() }));

// 3D tap the dragon itself (centre of the dais)
const dragPt = await page.evaluate(() => {
  const g = window.dragonGame;
  const v = new g.player.position.constructor(g.world.focus.x, g.world.focus.y + 2.5, g.world.focus.z);
  v.project(g.camera);
  return { x: (v.x * 0.5 + 0.5) * innerWidth, y: (-v.y * 0.5 + 0.5) * innerHeight };
});
await page.mouse.click(dragPt.x, dragPt.y);
await page.waitForTimeout(800);
out.tapDragon = await page.evaluate(() => ({ react: window.dragonGame.hangarReact, focus: window.dragonGame.hangarFocus }));

// buy a forest dragon from the market
await page.click('[data-action="goto"][data-id="shop"]');
await page.waitForTimeout(1200);
out.shopOwnedBefore = await page.evaluate(() => Object.keys(window.dragonUI.S.dragons).length);
await page.locator('.shop-card', { hasText: 'Mossback' }).locator('[data-action="buy-dragon"]').first().click();
await page.waitForTimeout(1600);
out.afterBuy = await page.evaluate(() => ({
  owned: Object.keys(window.dragonUI.S.dragons),
  mode: window.dragonGame.mode,
  ambient: window.dragonGame.hangarAmbient.length,
  selected: window.dragonUI.S.selected,
}));

// back to hangar and confirm the habitat has its dragon and roster counts
await page.click('[data-action="goto"][data-id="hangar"]');
await page.waitForTimeout(1500);
out.hangarAfterBuy = await page.evaluate(() => ({
  ambient: window.dragonGame.hangarAmbient.map(m => m.def.id),
  rows: document.querySelectorAll('.dragon-row').length,
  header: document.querySelector('.stat-pill')?.textContent?.trim(),
  chips: [...document.querySelectorAll('.habitat-chip')].map(c => c.textContent.replace(/\s+/g, ' ').trim()),
}));

// drag to orbit and wheel zoom
const beforeCam = await page.evaluate(() => window.dragonGame.hangarOrbit);
await page.mouse.move(600, 400); await page.mouse.down(); await page.mouse.move(700, 430, { steps: 8 }); await page.mouse.up();
await page.mouse.wheel(0, 300);
await page.waitForTimeout(400);
out.camera = await page.evaluate(() => ({ orbit: window.dragonGame.hangarOrbit, before: window.__b }));
await page.evaluate(() => { window.__b = null; });
out.camChanged = await page.evaluate((b) => {
  const o = window.dragonGame.hangarOrbit;
  return { yawChanged: Math.abs(o.yaw - b.yaw) > 0.01, dist: o.dist };
}, beforeCam);

await page.screenshot({ path: '/tmp/opencode/shots/final-hangar.png' });
console.log(JSON.stringify({ errors, out }, null, 2));
await browser.close();

