import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ args: ['--use-gl=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
await page.goto('http://localhost:3210/', { waitUntil: 'load' });
await page.waitForFunction(() => !document.getElementById('boot'), null, { timeout: 30000 }).catch(() => {});
await page.click('[data-action="goto"][data-id="hangar"]');
await page.waitForTimeout(1800);
const pts = await page.evaluate(() => {
  const g = window.dragonGame;
  return g.world.anchors.map(a => {
    const v = a.position.clone(); v.y += 1.4; v.project(g.camera);
    const x = (v.x * 0.5 + 0.5) * innerWidth, y = (-v.y * 0.5 + 0.5) * innerHeight;
    const el = document.elementFromPoint(x, y);
    return { family: a.family, x: Math.round(x), y: Math.round(y), el: el?.tagName + '.' + el?.className, onCanvas: el?.tagName === 'CANVAS' };
  });
});
console.log(JSON.stringify(pts, null, 2));
const hit = pts.find(p => p.onCanvas);
if (hit) {
  await page.mouse.click(hit.x, hit.y);
  await page.waitForTimeout(1000);
  console.log('after click', JSON.stringify(await page.evaluate(() => ({ focus: window.dragonGame.hangarFocus, active: document.querySelector('.habitat-chip.active')?.textContent?.replace(/\s+/g,' ').trim() }))));
}
console.log('errors', errors);
await browser.close();

import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ args: ['--use-gl=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
page.on('pageerror', e => console.log('ERR', e.message));
await page.goto('http://localhost:3210/', { waitUntil: 'load' });
await page.waitForFunction(() => !document.getElementById('boot'), null, { timeout: 30000 }).catch(() => {});
await page.click('[data-action="goto"][data-id="hangar"]');
await page.waitForTimeout(2000);
const dbg = await page.evaluate(() => {
  const g = window.dragonGame;
  const a = g.world.anchors.find(x => x.family === 'fire');
  const v = a.position.clone(); v.y += 1.4; v.project(g.camera);
  const cx = (v.x * 0.5 + 0.5) * innerWidth, cy = (-v.y * 0.5 + 0.5) * innerHeight;
  const THREE = g.player.position.constructor;
  const ndc = { x: (cx / innerWidth) * 2 - 1, y: -(cy / innerHeight) * 2 + 1 };
  // reconstruct raycaster using three from scene objects' constructors is hard; use game's import via dynamic? Just call handleTap.
  g.handleTap({ clientX: cx, clientY: cy });
  return {
    cx, cy, focus: g.hangarFocus,
    pickables: g.hangarPickables.map(o => o?.type || o?.userData?.interact?.type || o?.userData?.family || o?.name || 'group'),
    padCount: g.world.pads?.length,
    padInteract: g.world.pads?.[0]?.userData?.interact,
  };
});
console.log(JSON.stringify(dbg, null, 2));
await page.waitForTimeout(800);
console.log('focus after', JSON.stringify(await page.evaluate(() => window.dragonGame.hangarFocus)));
await browser.close();

