import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ args: ['--use-gl=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });
const results = {};

// desktop flow
{
  const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
  const errors = [];
  page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
  page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
  await page.goto('http://localhost:3210/', { waitUntil: 'load' });
  await page.waitForFunction(() => !document.getElementById('boot'), null, { timeout: 30000 }).catch(() => {});
  await page.waitForTimeout(900);

  // race hub regression
  await page.click('[data-action="goto"][data-id="race"]');
  await page.waitForTimeout(700);
  await page.screenshot({ path: '/tmp/opencode/shots/race-hub.png' });
  results.raceHub = await page.evaluate(() => ({ mode: window.dragonGame.mode, view: window.dragonUI.view, tracks: document.querySelectorAll('.track-card').length }));

  // hangar + ice filter
  await page.click('[data-action="goto"][data-id="hangar"]');
  await page.waitForTimeout(1500);
  await page.locator('.habitat-chip', { hasText: 'Ice' }).first().click();
  await page.waitForTimeout(1000);
  results.ice = await page.evaluate(() => ({
    note: document.querySelector('.habitat-note')?.textContent?.replace(/\s+/g, ' ').trim(),
    rows: document.querySelectorAll('.dragon-row').length,
    locked: document.querySelectorAll('.locked-row').length,
  }));
  await page.screenshot({ path: '/tmp/opencode/shots/final-ice.png' });

  // open a locked dragon modal
  await page.locator('.locked-row').first().click();
  await page.waitForTimeout(400);
  results.lockedModal = await page.evaluate(() => ({
    open: !document.getElementById('modal-root').classList.contains('hidden'),
    text: document.getElementById('modal-root').innerText.replace(/\s+/g, ' ').slice(0, 220),
    silhouette: document.querySelector('#modal-root img')?.src?.slice(0, 30),
  }));
  await page.screenshot({ path: '/tmp/opencode/shots/locked-modal.png' });
  await page.locator('#modal-root [data-action="close-modal"]').last().click();

  // training ring visit
  await page.locator('[data-action="hangar-visit"][data-id="training"]').click();
  await page.waitForTimeout(1200);
  await page.screenshot({ path: '/tmp/opencode/shots/final-training.png' });
  results.training = await page.evaluate(() => window.dragonGame.hangarFocus);

  // mobile
  await page.setViewportSize({ width: 390, height: 844 });
  await page.waitForTimeout(500);
  await page.evaluate(() => window.dragonUI.renderHangar());
  await page.waitForTimeout(900);
  await page.screenshot({ path: '/tmp/opencode/shots/final-mobile.png' });
  results.mobile = await page.evaluate(() => ({
    chips: document.querySelectorAll('.habitat-chip').length,
    scrollW: document.getElementById('screen').scrollWidth,
    clientW: document.getElementById('screen').clientWidth,
    overflowX: document.getElementById('screen').scrollWidth > document.getElementById('screen').clientWidth + 2,
  }));

  results.errors = errors.slice(0, 8);
  await page.close();
}
await browser.close();
console.log(JSON.stringify(results, null, 2));

