import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ args: ['--use-gl=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });
const out = {};
async function boot(width, height) {
  const page = await browser.newPage({ viewport: { width, height } });
  const errors = [];
  page.on('pageerror', e => errors.push(e.message));
  await page.goto('http://localhost:3210/', { waitUntil: 'load' });
  await page.waitForFunction(() => !document.getElementById('boot'), null, { timeout: 30000 }).catch(() => {});
  await page.waitForTimeout(800);
  return { page, errors };
}

// fresh mobile
{
  const { page, errors } = await boot(390, 844);
  await page.click('[data-action="goto"][data-id="hangar"]');
  await page.waitForTimeout(1800);
  await page.screenshot({ path: '/tmp/opencode/shots/mobile-fresh.png' });
  await page.locator('[data-action="hangar-visit"][data-id="training"]').click();
  await page.waitForTimeout(1500);
  await page.screenshot({ path: '/tmp/opencode/shots/mobile-training.png' });
  out.mobile = await page.evaluate(() => ({ orbit: window.dragonGame.hangarOrbit, narrow: window.dragonGame.hangarNarrow, focus: window.dragonGame.hangarFocus }));
  out.mobileErrors = errors;
  await page.close();
}
// desktop training framing
{
  const { page, errors } = await boot(1440, 900);
  await page.click('[data-action="goto"][data-id="hangar"]');
  await page.waitForTimeout(1500);
  await page.locator('[data-action="hangar-visit"][data-id="training"]').click();
  await page.waitForTimeout(1600);
  await page.screenshot({ path: '/tmp/opencode/shots/desktop-training2.png' });
  await page.locator('[data-action="hangar-visit"][data-id="feeding"]').click();
  await page.waitForTimeout(1600);
  await page.screenshot({ path: '/tmp/opencode/shots/desktop-feeding.png' });
  out.desktopErrors = errors;
  await page.close();
}
await browser.close();
console.log(JSON.stringify(out, null, 2));

