import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ args: ['--use-gl=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3210/', { waitUntil: 'load' });
await page.waitForFunction(() => !document.getElementById('boot'), null, { timeout: 30000 }).catch(() => {});
await page.waitForTimeout(700);
await page.click('[data-action="goto"][data-id="race"]');
await page.waitForTimeout(600);
await page.locator('[data-action="start-selected"]').click();
await page.waitForTimeout(3500);
const racing = await page.evaluate(() => ({
  mode: window.dragonGame.mode,
  view: window.dragonUI.view,
  hud: !document.getElementById('hud').classList.contains('hidden'),
  screenHidden: getComputedStyle(document.getElementById('screen')).display,
  fps: window.dragonGame.renderer.info.render.frame,
}));
await page.screenshot({ path: '/tmp/opencode/shots/race-live.png' });
// pause and quit
await page.evaluate(() => window.dragonUI.pauseRace());
await page.waitForTimeout(600);
const paused = await page.evaluate(() => ({ paused: window.dragonGame.paused, modal: !document.getElementById('modal-root').classList.contains('hidden') }));
await page.evaluate(() => window.dragonUI.quitRace());
await page.waitForTimeout(800);
const afterQuit = await page.evaluate(() => ({ mode: window.dragonGame.mode, view: window.dragonUI.view, screen: getComputedStyle(document.getElementById('screen')).display }));
console.log(JSON.stringify({ racing, paused, afterQuit, errors }, null, 2));
await browser.close();

