import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ args: ['--use-gl=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push(e.message));
await page.goto('http://localhost:3210/', { waitUntil: 'load' });
await page.waitForFunction(() => !document.getElementById('boot'), null, { timeout: 30000 }).catch(() => {});
await page.waitForTimeout(600);
// cheat coins and acquire a spread of species
const bought = await page.evaluate(() => {
  const ui = window.dragonUI;
  ui.S.coins = 2000000;
  const ids = ['titanwyrm', 'acidspit', 'serpens', 'runewyrm', 'zephyr', 'depthsong', 'prismwing', 'stormfrost', 'chronowing', 'crystalhorn'];
  const out = [];
  for (const id of ids) { ui.buyDragon(id); out.push(!!ui.S.dragons[id]); }
  return out;
});
await page.waitForTimeout(500);
const shots = [];
for (const id of ['titanwyrm', 'acidspit', 'serpens', 'zephyr', 'runewyrm', 'stormfrost']) {
  await page.evaluate((id) => { window.dragonUI.S.selected = id; window.dragonUI.dragonId = id; window.dragonGame.showHangar(id); window.dragonUI.renderHangar(); }, id);
  await page.waitForTimeout(1200);
  const geo = await page.evaluate(() => {
    const g = window.dragonGame;
    const box = new g.player.position.constructor().constructor ? null : null;
    return { id: g.playerModel.def.id, pos: g.player.position.toArray().map(n => +n.toFixed(2)), scale: g.playerModel.group.scale.x, ambient: g.hangarAmbient.length };
  });
  shots.push(geo);
  await page.screenshot({ path: `/tmp/opencode/shots/species-${id}.png` });
}
console.log(JSON.stringify({ bought, shots, errors }, null, 2));
await browser.close();

