const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');

const browser = await chromium.launch({ args: ['--use-gl=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3210/', { waitUntil: 'load' });
await page.waitForFunction(() => !document.getElementById('boot'), null, { timeout: 30000 }).catch(() => {});
await page.waitForTimeout(700);

const crown = await page.evaluate(async () => {
  const data = await import('/src/data.js');
  const ui = window.dragonUI;
  // pretend three leagues are already conquered; win the fourth now
  ui.S.leagues = {
    hatchling: { completed: true, wins: 1 },
    skyward: { completed: true, wins: 1 },
    storm: { completed: true, wins: 1 },
    legend: { completed: false, wins: 0 },
  };
  const league = data.LEAGUES.find(l => l.id === 'legend');
  const me = ui.S.riderName;
  ui.champ = {
    league, round: 3, points: { [me]: 30, 'Astrid Vane': 22 }, playerPoints: 30, results: [], finalized: false, lastProcessed: 3,
  };
  const res = ui.finalizeChampionship();
  return {
    owned: !!ui.S.dragons.aetherion,
    crownDragon: res?.crownDragon?.name || null,
    dragon: res?.dragon?.name || null,
    bonusDragon: res?.bonusDragon?.name || null,
    allComplete: data.LEAGUES.every(l => ui.S.leagues[l.id]?.completed),
  };
});

// hangar look + meter
await page.click('[data-action="goto"][data-id="hangar"]');
await page.waitForTimeout(1800);
const hangar = await page.evaluate(() => ({
  meter: document.querySelector('.collection-meter')?.textContent?.replace(/\s+/g, ' ').trim(),
  meterWidth: document.querySelector('.collection-meter .cm-bar i')?.style.width,
  chips: document.querySelectorAll('.habitat-chip').length,
  rows: document.querySelectorAll('.dragon-row').length,
  overflow: document.getElementById('screen').scrollWidth > document.getElementById('screen').clientWidth + 2,
}));
await page.screenshot({ path: '/tmp/opencode/shots/final2-desktop.png' });

// mobile pass
await page.setViewportSize({ width: 390, height: 844 });
await page.evaluate(() => window.dragonUI.renderHangar());
await page.waitForTimeout(1200);
const mobile = await page.evaluate(() => ({
  meter: document.querySelector('.collection-meter')?.textContent?.replace(/\s+/g, ' ').trim(),
  overflow: document.getElementById('screen').scrollWidth > document.getElementById('screen').clientWidth + 2,
  quality: window.dragonGame.quality,
  pixelRatio: window.dragonGame.renderer.getPixelRatio(),
}));
await page.screenshot({ path: '/tmp/opencode/shots/final2-mobile.png' });

console.log(JSON.stringify({ crown, hangar, mobile, errors }, null, 2));
await browser.close();

