  // level aura: subtle glow halo
  if (level >= 6) {
    const haloGeo = new THREE.RingGeometry(1.6, 1.76, 32); haloGeo.userData.dyn = true;
    const halo = new THREE.Mesh(haloGeo, new THREE.MeshBasicMaterial({
