import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ args: ['--use-gl=swiftshader', '--enable-webgl', '--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 1200, height: 800 } });
const errors = [];
page.on('pageerror', e => errors.push('PAGEERROR: ' + e.message));
page.on('console', m => { if (m.type() === 'error') errors.push('CONSOLE: ' + m.text()); });
await page.goto('http://localhost:3210/', { waitUntil: 'load' });
await page.waitForFunction(() => !document.getElementById('boot'), null, { timeout: 30000 }).catch(() => {});
const res = await page.evaluate(async () => {
  const { DRAGONS } = await import('/src/data.js');
  const { createDragon, dragonThumb } = await import('/src/dragon.js');
  const failed = [];
  const counts = {};
  for (const def of DRAGONS) {
    try {
      const m = createDragon(def, { level: 10, rider: false, castShadow: false });
      m.update(0.016, { flying: false, grounded: true, walk: 0.2 });
      m.update(0.016, { flying: true, speed: 60, bank: 0.3, boosting: true });
      let meshes = 0;
      m.group.traverse(o => { if (o.isMesh || o.isSprite) meshes++; });
      counts[def.family] = (counts[def.family] || 0) + 1;
      const thumb = dragonThumb(def, 64);
      if (!thumb || !thumb.startsWith('data:image/png')) throw new Error('thumb failed');
      m.group.traverse(o => { if (o.geometry?.userData?.dyn) o.geometry.dispose(); });
      if (meshes < 5) throw new Error('too few meshes ' + meshes);
    } catch (e) {
      failed.push({ id: def.id, err: e.message });
    }
  }
  return { total: DRAGONS.length, failed, counts };
});
console.log(JSON.stringify({ res, errors }, null, 2));
await browser.close();
EOF
