  ui.S.selected = 'aetherion';
  ui.dragonId = 'aetherion';
  window.dragonGame.showHangar('aetherion');
  ui.habitatFilter = 'all';
  ui.renderHangar();
  return { owned: Object.keys(ui.S.dragons).length, total: data.DRAGONS.length };
});
await page.waitForTimeout(1600);

// 2. Collection meter + habitat chips now populated
const board = await page.evaluate(() => ({
  meter: document.querySelector('.collection-meter')?.textContent?.replace(/\s+/g, ' ').trim(),
  meterWidth: document.querySelector('.collection-meter .cm-bar i')?.style.width,
  chips: [...document.querySelectorAll('.habitat-chip')].map(c => c.textContent.replace(/\s+/g, ' ').trim()),
  rows: document.querySelectorAll('.dragon-row').length,
}));
await page.screenshot({ path: '/tmp/opencode/shots/verify-all-owned.png' });

// 3. Info page + weakness in owned modal
const info = await page.evaluate(() => {
  const ui = window.dragonUI;
  ui.openDragonModal('aetherion');
  const txt = document.querySelector('.modal, #modal')?.textContent?.replace(/\s+/g, ' ').trim() || '';
  ui.closeModal();
  ui.openDragonModal('frostfang');
  const frost = document.querySelector('.modal, #modal')?.textContent?.replace(/\s+/g, ' ').trim() || '';
  ui.closeModal();
  return { aetherionHasWeak: /Weakness/i.test(txt), frostHasWeak: /Weakness/i.test(frost), frostSnippet: frost.slice(0, 220) };
});

// 4. Market filters across all families
const market = await page.evaluate(async () => {
  const data = await import('/src/data.js');
  const ui = window.dragonUI;
  ui.goto('shop');
  const out = {};
  for (const fam of data.FAMILY_ORDER) {
