    out[fam] = document.querySelectorAll('.shop-card, .market-card, [data-action="buy-dragon"]').length;
  }
  return out;
});

// 5. Race + explore still function
const race = await page.evaluate(async () => {
  const ui = window.dragonUI;
  ui.goto('race');
  ui.showRaceHub?.();
  return { view: ui.view, mode: window.dragonGame.mode };
});

// 6. Camera orbit + zoom sanity
await page.evaluate(() => { window.dragonUI.goto('hangar'); });
await page.waitForTimeout(1200);
const camBefore = await page.evaluate(() => ({ ...window.dragonGame.hangarOrbit }));
await page.mouse.move(720, 420); await page.mouse.down();
await page.mouse.move(860, 470, { steps: 12 }); await page.mouse.up();
await page.mouse.wheel(0, -300);
await page.waitForTimeout(600);
const camAfter = await page.evaluate(() => ({ ...window.dragonGame.hangarOrbit }));

// 7. Mobile
await page.setViewportSize({ width: 390, height: 844 });
await page.evaluate(() => { window.dragonUI.goto('hangar'); });
await page.waitForTimeout(1200);
const mobile = await page.evaluate(() => {
