    meter: document.querySelector('.collection-meter')?.textContent?.replace(/\s+/g, ' ').trim(),
  };
});
await page.screenshot({ path: '/tmp/opencode/shots/verify-mobile-full.png' });

console.log(JSON.stringify({ bulk, board, info, market, race, cam: { before: camBefore, after: camAfter }, mobile, errors }, null, 2));
await browser.close();
