import { createRequire } from 'node:module';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const browser = await chromium.launch({ args: ['--use-gl=swiftshader','--enable-webgl','--ignore-gpu-blocklist'] });
const page = await browser.newPage({ viewport: { width: 700, height: 500 } });
const errors = []; page.on('pageerror', e => errors.push(e.message));
await page.goto('http://localhost:3210/', { waitUntil: 'load' });
await page.waitForFunction(() => !document.getElementById('boot'), null, { timeout: 30000 }).catch(() => {});
const out = await page.evaluate(async () => {
  const { DRAGONS } = await import('/src/data.js');
  const { createDragon } = await import('/src/dragon.js');
  const THREE = await import('/vendor/three.module.js');
  const rows = [];
  for (const def of DRAGONS) {
    const m = createDragon(def, { level: 6, rider: false, castShadow: false });
    m.group.updateMatrixWorld(true);
    const b = new THREE.Box3().setFromObject(m.group);
    const s = new THREE.Vector3(); b.getSize(s);
    m.group.traverse(o => { if (o.geometry?.userData?.dyn) o.geometry.dispose(); });
    rows.push({ id: def.id, tail: def.shape.tailType || 'membrane', len: +s.z.toFixed(2), h: +s.y.toFixed(2), w: +s.x.toFixed(2), ratio: +(s.z / s.y).toFixed(2) });
  }
  const sorted = [...rows].sort((a, b) => b.ratio - a.ratio);
  return { longest: sorted.slice(0, 8), shortest: sorted.slice(-5), n: rows.length, errors };
});
console.log(JSON.stringify(out, null, 2));
await browser.close();
EOF
