369:   startLeagueRound() {
370:     const c = this.champ;
371:     if (!c) return;
372:     const trackId = c.league.tracks[Math.min(c.round, c.league.tracks.length - 1)];
373:     this.lastRaceConfig = { trackId, mode: 'championship', league: c.league, round: c.round + 1 };
