377:   processChampionshipResults(results) {
378:     const c = this.champ;
379:     if (!c || c.lastProcessed === c.round) return;
380:     c.lastProcessed = c.round;
381:     const pts = [10, 8, 6, 5, 4, 3];
382:     results.standings.forEach((s, i) => {
383:       c.points[s.name] = (c.points[s.name] || 0) + (pts[i] || 0);
384:     });
385:     c.playerPoints = c.points[this.S.riderName] || 0;
386:     c.results.push(results);
387:     c.round++;
388:   }
