390:   finalizeChampionship() {
391:     const c = this.champ;
392:     if (!c || c.finalized) return null;
393:     c.finalized = true;
394:     const ordered = Object.entries(c.points).sort((a, b) => b[1] - a[1]);
395:     const playerPlace = ordered.findIndex(([n]) => n === this.S.riderName) + 1;
396:     const league = c.league;
397:     const champ = playerPlace === 1;
398:     const rewards = { coins: Math.round(league.rewards.coins * (champ ? 1 : 0.45)), gems: champ ? league.rewards.gems : Math.round(league.rewards.gems / 2), dragon: null, track: null, champ, playerPlace, ordered };
399:     Save.awardCoins(rewards.coins);
400:     Save.awardGems(rewards.gems);
401:     Save.addRiderXp(320);
402:     if (champ && league.rewards.track) { if (Save.unlockTrack(league.rewards.track)) rewards.track = TRACK_MAP[league.rewards.track]; }
403:     if (champ && league.rewards.dragon) {
404:       if (Save.addDragon(league.rewards.dragon, 3)) rewards.dragon = DRAGON_MAP[league.rewards.dragon];
405:       else { Save.awardGems(10); rewards.duplicate = true; }
406:     }
407:     if (champ && league.rewards.bonusDragon) {
408:       if (Save.addDragon(league.rewards.bonusDragon, 5)) rewards.bonusDragon = DRAGON_MAP[league.rewards.bonusDragon];
409:       else { Save.awardGems(14); }
410:     }
411:     Save.addDragonXp(this.S.selected, 260);
412:     const progress = Save.leagueProgress(league.id);
413:     Save.saveLeague(league.id, {
414:       completed: champ || !!progress.completed,
415:       wins: champ ? (progress.wins || 0) + 1 : (progress.wins || 0),
416:       bestPos: Math.min(progress.bestPos || 9, playerPlace), points: c.playerPoints,
417:     });
418:     // Conquer every league and the Dragon's Crown is yours — along with the
419:     // mythical Aetherion, whose unlock condition names exactly that feat.
420:     if (LEAGUES.every(l => Save.leagueProgress(l.id).completed) && Save.addDragon('aetherion', 6)) {
421:       rewards.crownDragon = DRAGON_MAP.aetherion;
422:     }
423:     Save.save();
424:     this.updateChrome();
425:     return { ...rewards, league, standings: ordered };
426:   }
