555:   bindHudControls() {
556:     const joy = $('#joystick');
557:     const knob = $('#joy-knob');
558:     if (joy && knob) {
559:       let active = false, id = null;
560:       const reset = () => {
561:         active = false; id = null; this.game.setSteer(0, 0);
562:         knob.style.transform = 'translate(-50%, -50%)';
563:       };
564:       const move = (e) => {
565:         const r = joy.getBoundingClientRect();
566:         const cx = r.left + r.width / 2, cy = r.top + r.height / 2;
567:         let dx = e.clientX - cx, dy = e.clientY - cy;
568:         const max = r.width / 2 - 26;
569:         const d = Math.hypot(dx, dy);
570:         if (d > max) { dx = dx / d * max; dy = dy / d * max; }
571:         this.game.setSteer(dx / max, -dy / max);
572:         knob.style.transform = `translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px))`;
573:       };
574:       joy.addEventListener('pointerdown', (e) => {
575:         e.preventDefault(); e.stopPropagation();
576:         active = true; id = e.pointerId; joy.setPointerCapture(e.pointerId); move(e);
577:       });
578:       joy.addEventListener('pointermove', (e) => { if (active && e.pointerId === id) { e.preventDefault(); move(e); } });
579:       ['pointerup', 'pointercancel', 'lostpointercapture'].forEach(ev => joy.addEventListener(ev, (e) => { if (e.pointerId === id || ev === 'lostpointercapture') reset(); }));
580:     }
581:     const boost = $('#boost-btn');
582:     if (boost) {
583:       const on = (e) => { e.preventDefault(); e.stopPropagation(); this.game.setBoost(true); boost.classList.add('pressed', 'on'); };
584:       const off = (e) => { this.game.setBoost(false); boost.classList.remove('pressed', 'on'); };
585:       boost.addEventListener('pointerdown', (e) => { on(e); boost.setPointerCapture?.(e.pointerId); });
586:       boost.addEventListener('pointerup', off);
587:       boost.addEventListener('pointercancel', off);
588:       boost.addEventListener('pointerleave', off);
589:       boost.addEventListener('contextmenu', e => e.preventDefault());
590:     }
591:     const brake = $('#brake-btn');
592:     if (brake) {
593:       brake.addEventListener('pointerdown', (e) => { e.preventDefault(); this.game.setBrake(true); brake.classList.add('pressed'); });
594:       ['pointerup', 'pointercancel', 'pointerleave'].forEach(ev => brake.addEventListener(ev, () => { this.game.setBrake(false); brake.classList.remove('pressed'); }));
595:     }
596:     // Ability + manoeuvre use the delegated [data-action] handler so they fire
597:     // once per tap on both touch and pointer devices.
