686:   drawMinimap() {
687:     const c = $('#minimap');
688:     if (!c || !this.hudData) return;
689:     const ctx = c.getContext('2d');
690:     const w = c.width, h = c.height;
691:     ctx.clearRect(0, 0, w, h);
692:     // background
693:     const bg = ctx.createRadialGradient(w * 0.5, h * 0.45, 10, w * 0.5, h * 0.5, w * 0.55);
694:     bg.addColorStop(0, 'rgba(20,48,57,.85)'); bg.addColorStop(1, 'rgba(4,13,19,.9)');
695:     ctx.fillStyle = bg; ctx.fillRect(0, 0, w, h);
696:     const outline = this.game.raceOutline;
697:     if (!outline) return;
698:     const pad = 34, size = w - pad * 2;
699:     const map = ([x, z]) => [pad + x * size, pad + z * size];
700:     ctx.lineJoin = 'round'; ctx.lineCap = 'round';
701:     ctx.beginPath();
702:     outline.forEach((pt, i) => { const [x, y] = map(pt); i === 0 ? ctx.moveTo(x, y) : ctx.lineTo(x, y); });
703:     ctx.closePath();
704:     ctx.strokeStyle = 'rgba(255,209,102,.22)'; ctx.lineWidth = 16; ctx.stroke();
705:     ctx.strokeStyle = 'rgba(255,224,160,.85)'; ctx.lineWidth = 3; ctx.stroke();
706:     // checkpoint dots
707:     const gateCount = this.game.world?.gates?.length || 20;
708:     for (let i = 0; i < 20; i += 5) {
709:       const p = this.game.world.curve.getPointAt(i / 20);
710:       const [x, y] = map([(p.x - this.game.race.bounds.minX) / this.game.race.bounds.span, (p.z - this.game.race.bounds.minZ) / this.game.race.bounds.span]);
711:       ctx.beginPath(); ctx.arc(x, y, 4, 0, 7); ctx.fillStyle = 'rgba(111,232,212,.7)'; ctx.fill();
712:     }
713:     // AI
714:     (this.hudData.minimap || []).forEach(r => {
715:       if (r.eliminated) return;
716:       ctx.beginPath(); ctx.arc(pad + r.x * size, pad + r.z * size, 4.5, 0, 7);
717:       ctx.fillStyle = 'rgba(255,123,169,.9)'; ctx.fill();
718:     });
719:     // player
720:     const px = pad + this.hudData.player.x * size;
721:     const py = pad + this.hudData.player.z * size;
722:     const yaw = this.game.flight.yaw;
723:     ctx.save(); ctx.translate(px, py); ctx.rotate(-yaw);
724:     ctx.beginPath(); ctx.moveTo(0, -9); ctx.lineTo(6, 7); ctx.lineTo(0, 3.5); ctx.lineTo(-6, 7); ctx.closePath();
725:     ctx.fillStyle = '#ffe6a0'; ctx.shadowColor = '#ffd166'; ctx.shadowBlur = 12; ctx.fill(); ctx.restore();
726:     // border
727:     ctx.beginPath(); ctx.arc(w / 2, h / 2, w / 2 - 4, 0, 7); ctx.strokeStyle = 'rgba(255,209,102,.18)'; ctx.lineWidth = 5; ctx.stroke();
728:   }
