301:   // Hard LOD for background roost dragons: at habitat distance the nostrils,
302:   // claws and teeth are sub-pixel, so drop every mesh smaller than ~2% of the
303:   // body height. Eyes are preserved so blinking still reads. This cuts dozens
304:   // of draw calls per ambient dragon on mobile without any visible change.
305:   simplifyDragon(model, threshold = 0.022) {
306:     const keep = new Set(model.group.userData.eyeMeshes || []);
307:     const box = new THREE.Box3().setFromObject(model.group);
308:     const h = Math.max(0.001, box.max.y - box.min.y);
309:     const drop = [];
310:     model.group.traverse(o => {
311:       if (!o.isMesh || keep.has(o)) return;
312:       o.geometry.computeBoundingSphere();
313:       const r = (o.geometry.boundingSphere?.radius || 0) * Math.max(o.scale.x, o.scale.y, o.scale.z);
314:       if (r > 0 && r < h * threshold) drop.push(o);
315:     });
316:     drop.forEach(o => o.parent?.remove(o));
317:     this.hangarLodSaved = (this.hangarLodSaved || 0) + drop.length;
318:     return drop.length;
319:   }
