import * as THREE from '../vendor/three.module.js';
import { DRAGON_MAP, DRAGON_MAP as DM, FAMILY_ORDER, TRACK_MAP, LEAGUES, EXPLORE_ZONES, RIVAL_NAMES, AI_DRAGONS } from './data.js';
