281:   if (!d) return 0;
282:   const hallBonus = 1 + BUILDINGS.find(b => b.id === 'hall').bonus[state.village.hall || 0];
283:   d.xp += Math.round(n * hallBonus);
284:   let ups = 0;
285:   while (d.xp >= dragonXpNeed(d.level) && d.level < 30) {
286:     d.xp -= dragonXpNeed(d.level);
287:     d.level++;
288:     ups++;
289:   }
290:   d.stage = stageForLevel(d.level);
291:   if (ups) {
292:     const hall = BUILDINGS.find(b => b.id === 'hall');
293:     state.log.unshift({ t: Date.now(), text: `${DRAGON_MAP[id].name} reached level ${d.level}! ${hall ? '' : ''}`, kind: 'level' });
294:   }
295:   save();
296:   return ups;
297: }
