323: export function upgradeDragonStat(id, stat) {
324:   const d = state.dragons[id];
325:   if (!d) return { ok: false, msg: 'No dragon.' };
326:   if (d.upgrades[stat] >= 6) return { ok: false, msg: 'That trait is fully trained.' };
327:   if (d.level < 2 + d.upgrades[stat] * 1) return { ok: false, msg: 'Level up your dragon first.' };
328:   const cost = upgradeCost(stat, d.upgrades[stat]);
329:   if (state.coins < cost) return { ok: false, msg: 'Not enough coins.' };
330:   state.coins -= cost;
331:   d.upgrades[stat]++;
332:   state.stats.upgrades++;
333:   progressDaily('upgrades', 1);
334:   addDragonXp(id, 40);
335:   save();
336:   return { ok: true, msg: `${stat} upgraded!` };
337: }
