345: export function canUnlockSkill(id, skill) {
346:   const d = state.dragons[id];
347:   if (!d) return { ok: false, reason: 'No dragon.' };
348:   if (d.skills.includes(skill.id)) return { ok: false, reason: 'Already learned.' };
349:   if (skillPoints(id) < skill.cost) return { ok: false, reason: 'No skill points.' };
350:   if (d.level < skill.req) return { ok: false, reason: `Requires level ${skill.req}.` };
351:   const group = Object.values(SKILLS).find(g => g.some(s => s.id === skill.id));
352:   const prev = group[group.indexOf(skill) - 1];
353:   if (prev && !d.skills.includes(prev.id)) return { ok: false, reason: `Learn ${prev.name} first.` };
354:   return { ok: true };
355: }
