357: export function unlockSkill(id, skill) {
358:   const check = canUnlockSkill(id, skill);
359:   if (!check.ok) return check;
360:   state.dragons[id].skills.push(skill.id);
361:   addDragonXp(id, 50);
362:   save();
363:   return { ok: true, msg: `${skill.name} learned!` };
364: }
