1545:   handleAction(a, id, el) {
1546:     switch (a) {
1547:       case 'goto': this.goto(id); break;
1548:       case 'quick-race': this.startQuickRace(); break;
1549:       case 'select-mode': this.modeId = id; this.renderRaceHub(); break;
1550:       case 'select-track':
1551:         this.trackId = id;
1552:         if (!this.S.unlockedTracks.includes(id)) { this.toast('That sky is still locked.', 'Win the linked championship to unlock it', ''); }
1553:         this.renderRaceHub(); break;
1554:       case 'pick-league':
1555:         this.leagueId = id; this.modeId = 'championship'; this.renderRaceHub();
1556:         this.toast('Championship selected.', 'Press Enter Championship to join', 'good'); break;
1557:       case 'start-selected': this.startSelectedRace(); break;
1558:       case 'enter-champ': this.confirmChampionship(id); break;
1559:       case 'start-championship': this.closeModal(); this.startChampionship(id); break;
1560:       case 'start-event': this.startEventRace(); break;
1561:       case 'claim-season': this.claimSeasonReward(); break;
1562:       case 'claim-daily': {
1563:         const ch = this.dailyList().find(c => c.id === id);
1564:         if (ch && Save.claimDaily(ch)) {
1565:           sfx('pickup');
1566:           this.toast('Daily trial complete!', `+${ch.coins} coins · +${ch.xp} dragon XP`, 'good');
1567:           this.updateChrome();
1568:           if (this.view === 'menu') this.renderMenu(); else if (this.view === 'race') this.renderRaceHub();
1569:         }
1570:         break;
1571:       }
1572:       case 'hangar-tab': this.hangarTab = id; this.renderHangar(); break;
1573:       case 'hangar-habitat-filter': {
1574:         this.habitatFilter = id;
1575:         if (id === 'all') this.game.focusHangarDragon?.();
1576:         else this.game.focusHangarHabitat?.(id);
1577:         this.renderHangar();
1578:         break;
1579:       }
1580:       case 'hangar-visit': this.visitHangar(id); break;
1581:       case 'select-dragon': {
1582:         if (!this.S.dragons[id]) { this.inspectLocked(id); break; }
1583:         this.S.selected = id; this.dragonId = id; Save.save();
1584:         this.game.showHangar(id);
1585:         this.renderHangar(); this.updateChrome();
