337:   getLeaderboard(track) {
338:     const seed = [...track.id].reduce((a, c) => a + c.charCodeAt(0), 0);
339:     const base = (track.length / 64) * track.laps;
340:     const names = RIVAL_NAMES.slice(0).sort((a, b) => ((seed * a.length) % 17) - ((seed * b.length) % 17));
341:     const rows = [];
342:     for (let i = 0; i < 4; i++) {
343:       rows.push({ name: names[i % names.length], time: base * (0.92 + ((seed + i * 37) % 23) / 100) });
344:     }
345:     const pb = this.S.bestTimes[track.id];
346:     if (pb) rows.push({ name: this.S.riderName, time: pb, me: true });
347:     else rows.push({ name: this.S.riderName, time: null, me: true });
348:     rows.sort((a, b) => (a.time ?? 9999) - (b.time ?? 9999));
349:     return rows.slice(0, 5).map((r, i) => ({ ...r, pos: i + 1, time: r.time ?? 9999, name: r.time == null ? r.name + ' (you)' : r.name }));
350:   }
