139: const BREEDING_MS = 30 * 60 * 1000;
140: const GENE_STATS = ['speed', 'accel', 'stamina', 'handling'];
141: const randomItem = list => list[Math.floor(Math.random() * list.length)];
142: 
143: function parentId(parent) { return typeof parent === 'string' ? parent : parent?.id; }
144: function baseGenes(id) {
145:   const def = DRAGON_MAP[id];
146:   const savedGenes = state.dragons[id]?.genes?.stats;
147:   return Object.fromEntries(GENE_STATS.map(key => [key, Number(savedGenes?.[key] ?? def?.stats?.[key] ?? 5)]));
148: }
149: function chooseOffspring(parentIds) {
150:   const reserved = new Set(state.eggs.map(egg => egg.speciesId));
151:   const available = DRAGONS.filter(def => !state.dragons[def.id] && !reserved.has(def.id));
152:   if (!available.length) return null;
153:   const parents = parentIds.map(id => DRAGON_MAP[id]);
154:   const families = parents.map(p => p?.family).filter(Boolean);
155:   const mutation = Math.random() < 0.08;
156:   const pool = mutation ? available : available.filter(def => families.includes(def.family));
157:   const choices = pool.length ? pool : available;
158:   const weighted = choices.flatMap(def => {
159:     const matching = families.includes(def.family);
160:     return Array(Math.max(1, matching ? 4 : 1)).fill(def);
161:   });
162:   return { def: randomItem(weighted), mutation };
163: }
