165: /** Start breeding two owned dragons. Species are unique in the current save model. */
166: export function breedDragons(parentA, parentB) {
167:   const parentIds = [parentId(parentA), parentId(parentB)];
168:   if (parentIds.some(id => !id || !state.dragons[id])) return { ok: false, msg: 'Both parents must be dragons you own.' };
169:   if (parentIds[0] === parentIds[1]) return { ok: false, msg: 'Choose two different parents.' };
170:   const offspring = chooseOffspring(parentIds);
171:   if (!offspring) return { ok: false, msg: 'There are no unowned dragon species left to hatch.' };
172:   const { def, mutation } = offspring;
173:   const inherited = parentIds.map(baseGenes);
174:   const genes = { stats: {} };
175:   for (const key of GENE_STATS) {
176:     const inheritedValue = (inherited[0][key] + inherited[1][key]) / 2;
177:     let value = def.stats[key] * 0.65 + inheritedValue * 0.35;
178:     if (mutation) value += Math.random() < 0.5 ? -1.5 : 1.5;
179:     genes.stats[key] = Math.round(Math.max(1, Math.min(12, value)) * 10) / 10;
180:   }
181:   const createdAt = Date.now();
182:   const egg = {
183:     id: `egg-${createdAt.toString(36)}-${Math.random().toString(36).slice(2, 8)}`,
184:     speciesId: def.id, parentIds, genes, mutation, createdAt, hatchAt: createdAt + BREEDING_MS,
185:   };
186:   state.eggs.push(egg);
187:   save();
188:   return { ok: true, egg };
189: }
