366: // Effective stats combining base, level, upgrades, bond and skills
367: export function statsOf(id) {
368:   const def = DRAGON_MAP[id];
369:   const d = state.dragons[id];
370:   if (!def) return { topSpeed: 80, accel: 20, turn: 1.5, staminaMax: 100 };
371:   if (!d) {
372:     const b = def.stats;
373:     return {
374:       topSpeed: 46 + b.speed * 3.4, accel: 10 + b.accel * 1.6, turn: 0.9 + b.handling * 0.085,
375:       staminaMax: 60 + b.stamina * 5, agil: b.handling, atk: b.speed,
376:     };
377:   }
378:   const arena = BUILDINGS.find(b => b.id === 'arena');
379:   const arenaMult = 1 + (arena.bonus[state.village.arena || 0] || 0);
380:   const skillBoost = {
381:     speed: d.skills.some(s => s === 'sp1') ? 0.06 : 0,
382:     speed2: d.skills.some(s => s === 'sp3') ? 0.12 : 0,
383:     boost: d.skills.some(s => s === 'sp2') ? 0.1 : 0,
384:     turn: d.skills.some(s => s === 'ac1') ? 0.10 : 0,
385:     turn2: d.skills.some(s => s === 'ac3') ? 0.15 : 0,
386:     stamina: d.skills.some(s => s === 'en1') ? 0.15 : 0,
387:     regen: d.skills.some(s => s === 'en2') ? 0.35 : 0,
388:     boostCost: d.skills.some(s => s === 'en3') ? 0.25 : 0,
389:   };
390:   const lvl = 1 + (d.level - 1) * 0.035;
391:   const training = d.academy?.bonuses || {};
392:   const bond = 1 + (d.bondLevel - 1) * 0.02 + (training.bond || 0) * 0.005;
393:   const ups = d.upgrades;
394:   const b = { ...def.stats, ...(d.genes?.stats || {}) };
395:   b.speed += (training.speed || 0) * 0.35 + (training.focus || 0) * 0.1;
396:   b.accel += (training.flight || 0) * 0.35 + (training.focus || 0) * 0.1;
397:   b.stamina += (training.endurance || 0) * 0.35;
398:   b.handling += (training.agility || 0) * 0.35;
399:   const speed = 46 + b.speed * 3.4 + ups.speed * (2.1 * arenaMult);
400:   const topSpeed = speed * (1 + skillBoost.speed + skillBoost.speed2) * lvl * bond;
401:   const accel = (10 + b.accel * 1.6 + ups.accel * (1.7 * arenaMult)) * lvl;
402:   const turn = (0.9 + b.handling * 0.085 + ups.handling * (0.035 * arenaMult)) * (1 + skillBoost.turn + skillBoost.turn2);
403:   const staminaMax = (60 + b.stamina * 5 + ups.stamina * (9 * arenaMult)) * (1 + skillBoost.stamina);
404:   return {
405:     topSpeed, accel, turn, staminaMax,
406:     boostMult: 1.34 + skillBoost.boost, boostCost: 18 * (1 - skillBoost.boostCost),
407:     regen: 7 * (1 + skillBoost.regen),
408:     agil: Math.round((b.handling + ups.handling * 0.8 + d.bondLevel * 0.25) * 10) / 10,
409:     atk: Math.round((b.speed + ups.speed * 0.8) * 10) / 10,
410:     stamina: Math.round((b.stamina + ups.stamina * 0.8) * 10) / 10,
411:     accelStat: Math.round((b.accel + ups.accel * 0.8) * 10) / 10,
412:   };
413: }
