416: function hashDate(str) {
417:   let h = 2166136261;
418:   for (let i = 0; i < str.length; i++) { h ^= str.charCodeAt(i); h = Math.imul(h, 16777619); }
419:   return Math.abs(h);
420: }
421: export function activeDailies() {
422:   const seed = hashDate(today() + '-skyfire');
423:   const pool = [...DAILY_POOL];
424:   const picked = [];
425:   for (let i = 0; i < 3 && pool.length; i++) {
426:     const idx = (seed >> (i * 5)) % pool.length;
427:     picked.push(pool.splice(idx, 1)[0]);
428:   }
429:   return picked;
430: }
